-- GENERATED by scripts/bundle-migrations.sh — do not edit. Edit the migrations.
-- Runs inside one transaction: any failure rolls the whole thing back.
-- Not idempotent. Run once on an empty project.

begin;

do $$
begin
  if exists (
    select 1 from pg_type t
    join pg_namespace n on n.oid = t.typnamespace
    where n.nspname = 'app' and t.typname = 'member_role'
  ) then
    raise exception
      'Already applied: this project already has the Virally schema. This bundle is not idempotent and nothing was changed — the transaction is rolling back, so the existing database is untouched. To rebuild from scratch you must reset the database first.';
  end if;
end;
$$;

-- ── 0001_foundation.sql ──
-- =============================================================================
-- 0001 — FOUNDATION
--
-- Extensions, the private `app` schema, shared enums, and the timestamp trigger.
--
-- Everything in `app` is deliberately excluded from the exposed API schemas in
-- config.toml. It holds the authorization helpers and the role→permission table:
-- data the client must be able to *benefit* from but never read or modify.
-- =============================================================================

create extension if not exists "pgcrypto" with schema extensions;
create extension if not exists "pg_trgm" with schema extensions;

create schema if not exists app;

revoke all on schema app from public;
revoke all on schema app from anon, authenticated;
-- `usage` only: it lets RLS policies call the helper functions without granting
-- the ability to enumerate or read anything the schema contains.
grant usage on schema app to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- TIMESTAMPS
--
-- `updated_at` is maintained by trigger, never by the application. A client that
-- sets it itself will eventually forget to, and "when did this last change" is
-- load-bearing for autosave conflict detection and analytics freshness.
-- -----------------------------------------------------------------------------
create or replace function app.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

comment on function app.touch_updated_at is
  'BEFORE UPDATE trigger. Sets updated_at to now() regardless of what the client sent.';

-- Attaches the trigger to any table that has an `updated_at` column.
create or replace function app.attach_touch_trigger(p_table regclass)
returns void
language plpgsql
as $$
declare
  v_name text := format('touch_%s', split_part(p_table::text, '.', 2));
begin
  execute format(
    'create trigger %I before update on %s for each row execute function app.touch_updated_at()',
    v_name, p_table
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- SHARED ENUMS
--
-- Enums rather than text+CHECK where the set is genuinely closed and shared
-- across tables: it gives one authoritative list, and adding a value becomes a
-- deliberate migration instead of a typo that silently creates a new status.
-- -----------------------------------------------------------------------------

-- Organisation-level roles. Ordered least→most privileged for readability only;
-- privilege is resolved through app.role_permissions, not enum ordering.
create type app.member_role as enum (
  'viewer',
  'analyst',
  'reviewer',
  'publisher',
  'editor',
  'strategist',
  'admin',
  'owner'
);

-- Discrete capabilities. Deliberately finer-grained than roles so that
-- "who may publish" is separable from "who may create", which is the whole
-- point of an approval workflow.
create type app.permission as enum (
  'content.create',
  'content.approve',
  'content.publish',
  'content.delete',
  'campaign.manage',
  'accounts.connect',
  'accounts.disconnect',
  'analytics.view',
  'billing.view',
  'billing.manage',
  'team.manage',
  'workspace.manage',
  'assets.delete'
);

create type app.platform as enum (
  'instagram',
  'facebook',
  'tiktok',
  'youtube'
);

create type app.aspect_ratio as enum (
  '9:16',
  '4:5',
  '1:1',
  '16:9',
  '4:3',
  '3:2',
  'custom'
);

-- Lifecycle shared by campaigns, content and variants.
create type app.review_status as enum (
  'draft',
  'awaiting_review',
  'approved',
  'rejected',
  'archived'
);

create type app.job_status as enum (
  'pending',
  'queued',
  'running',
  'waiting_external',
  'completed',
  'failed',
  'cancelled',
  'dead_letter'
);

create type app.publish_status as enum (
  'draft',
  'awaiting_review',
  'approved',
  'scheduled',
  'queued',
  'uploading',
  'publishing',
  'published',
  'failed',
  'cancelled'
);

create type app.connection_health as enum (
  'healthy',
  'expired',
  'limited',
  'rate_limited',
  'failing',
  'disconnected'
);

create type app.asset_kind as enum (
  'source_video',
  'generated_video',
  'image',
  'generated_image',
  'audio',
  'voiceover',
  'music',
  'thumbnail',
  'document',
  'brand_asset',
  'export'
);

-- Distinguishes real provider output from mock output. Every surface that
-- displays a generated asset reads this to decide whether to show the "Demo
-- data" label, which is why it lives in the schema and not in application code.
create type app.output_origin as enum (
  'provider',
  'mock',
  'user_upload',
  'seeded_demo'
);

-- -----------------------------------------------------------------------------
-- ROLE → PERMISSION MAP
--
-- A table rather than a CASE expression so the team screen can render the real
-- matrix instead of a hardcoded copy of it that drifts.
-- -----------------------------------------------------------------------------
create table app.role_permissions (
  role app.member_role not null,
  permission app.permission not null,
  primary key (role, permission)
);

insert into app.role_permissions (role, permission)
select r.role, p.permission
from (values
  -- Owner and admin hold everything; the difference is enforced separately —
  -- an admin cannot remove the owner or delete the organisation.
  ('owner'::app.member_role, 'all'),
  ('admin'::app.member_role, 'all')
) as r(role, marker)
cross join (select unnest(enum_range(null::app.permission)) as permission) p
where r.marker = 'all';

insert into app.role_permissions (role, permission) values
  -- Strategist: shapes and runs campaigns end to end, but does not touch
  -- billing, team membership or account connections.
  ('strategist', 'content.create'),
  ('strategist', 'content.approve'),
  ('strategist', 'campaign.manage'),
  ('strategist', 'analytics.view'),

  -- Editor: makes things. Explicitly cannot approve their own work or publish.
  ('editor', 'content.create'),
  ('editor', 'analytics.view'),

  -- Reviewer: approves or rejects, but cannot author or publish. Separating
  -- these three is what makes the approval step meaningful.
  ('reviewer', 'content.approve'),
  ('reviewer', 'analytics.view'),

  -- Publisher: pushes approved content to authorised accounts. Cannot approve.
  ('publisher', 'content.publish'),
  ('publisher', 'analytics.view'),

  ('analyst', 'analytics.view'),
  ('viewer', 'analytics.view');

comment on table app.role_permissions is
  'Authoritative role→permission matrix. Read by app.has_permission() and by the team UI. Never expose over the API.';

-- ── 0002_tenancy.sql ──
-- =============================================================================
-- 0002 — TENANCY
--
-- profiles · organizations · organization_members · workspaces ·
-- workspace_members, plus the authorization helpers every later policy calls.
--
-- THE RECURSION PROBLEM, AND WHY EVERY HELPER IS SECURITY DEFINER
--
-- The natural policy on `organization_members` is "you may read rows for orgs you
-- belong to" — which requires reading `organization_members`, whose policy
-- requires reading `organization_members`. Postgres detects this and raises
-- `infinite recursion detected in policy`.
--
-- The fix is that every helper below is SECURITY DEFINER, so it executes as its
-- owner and is not itself subject to RLS. Policies call the helper instead of
-- re-querying the table. This is the standard Supabase pattern and the reason
-- these functions cannot be plain views.
--
-- Each one therefore pins `search_path` explicitly. A SECURITY DEFINER function
-- with a mutable search_path is a privilege-escalation vector: a caller who can
-- create a table in an earlier schema can shadow the ones we meant to read.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- PROFILES
-- One row per auth user. Never stores credentials — Supabase Auth owns those.
-- -----------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text,
  full_name text,
  avatar_url text,
  locale text not null default 'en',
  timezone text not null default 'UTC',
  -- Notification preferences live here rather than in a separate table: they are
  -- strictly one-to-one with the profile and always read together with it.
  notification_preferences jsonb not null default
    '{"job_failed":true,"approval_required":true,"publish_failed":true,"usage_warning":true,"weekly_digest":false}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.profiles');

-- -----------------------------------------------------------------------------
-- ORGANIZATIONS
-- The billing and ownership boundary. Cross-organization access is denied
-- unconditionally — this is the line the isolation tests assert.
-- -----------------------------------------------------------------------------
create table public.organizations (
  id uuid primary key default extensions.gen_random_uuid(),
  name text not null check (length(trim(name)) between 1 and 120),
  slug text not null unique check (slug ~ '^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$'),
  -- Answers step 1 of onboarding: creator / agency / company / network.
  account_type text not null default 'personal'
    check (account_type in ('personal', 'agency', 'company', 'network')),
  created_by uuid not null references auth.users (id) on delete restrict,
  -- Soft delete: an organisation holds published-post history and a usage ledger
  -- that must survive cancellation for audit and billing dispute purposes.
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.organizations');

create table public.organization_members (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  role app.member_role not null default 'viewer',
  invited_by uuid references auth.users (id) on delete set null,
  accepted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- One membership per user per organisation. This constraint is what makes the
  -- bootstrap function idempotent under a replayed OAuth callback.
  unique (organization_id, user_id)
);

select app.attach_touch_trigger('public.organization_members');

-- -----------------------------------------------------------------------------
-- WORKSPACES
-- A workspace scopes campaigns, content and connected accounts within an
-- organisation — an agency's client, or a media network's brand cluster.
-- -----------------------------------------------------------------------------
create table public.workspaces (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  name text not null check (length(trim(name)) between 1 and 120),
  slug text not null check (slug ~ '^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$'),
  is_default boolean not null default false,
  deleted_at timestamptz,
  created_by uuid not null references auth.users (id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, slug)
);

select app.attach_touch_trigger('public.workspaces');

-- Exactly one default workspace per organisation. A partial unique index rather
-- than a trigger: the database enforces it even for service-role writes.
create unique index workspaces_one_default_per_org
  on public.workspaces (organization_id)
  where is_default and deleted_at is null;

create table public.workspace_members (
  id uuid primary key default extensions.gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  organization_id uuid not null references public.organizations (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  -- Overrides the organisation role *within this workspace only*. Null means
  -- "inherit the organisation role", which is the common case.
  role app.member_role,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, user_id)
);

select app.attach_touch_trigger('public.workspace_members');

-- =============================================================================
-- AUTHORIZATION HELPERS
-- =============================================================================

-- Organisation membership. The base predicate for nearly every policy.
create or replace function app.is_org_member(p_organization_id uuid)
returns boolean
language sql
security definer
set search_path = public, pg_catalog
stable
as $$
  select exists (
    select 1
    from public.organization_members m
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
  );
$$;

-- The caller's effective role in an organisation.
create or replace function app.org_role(p_organization_id uuid)
returns app.member_role
language sql
security definer
set search_path = public, pg_catalog
stable
as $$
  select m.role
  from public.organization_members m
  where m.organization_id = p_organization_id
    and m.user_id = auth.uid();
$$;

-- Workspace membership.
--
-- Organisation owners and admins are members of every workspace implicitly —
-- otherwise an owner could create a workspace and immediately lose access to it.
create or replace function app.is_workspace_member(p_workspace_id uuid)
returns boolean
language sql
security definer
set search_path = public, pg_catalog
stable
as $$
  select exists (
    select 1
    from public.workspace_members wm
    where wm.workspace_id = p_workspace_id
      and wm.user_id = auth.uid()
  )
  or exists (
    select 1
    from public.workspaces w
    join public.organization_members m
      on m.organization_id = w.organization_id
    where w.id = p_workspace_id
      and m.user_id = auth.uid()
      and m.role in ('owner', 'admin')
  );
$$;

-- Effective role for a workspace: the workspace override if set, else the
-- organisation role.
create or replace function app.workspace_role(p_workspace_id uuid)
returns app.member_role
language sql
security definer
set search_path = public, pg_catalog
stable
as $$
  select coalesce(
    (
      select wm.role
      from public.workspace_members wm
      where wm.workspace_id = p_workspace_id
        and wm.user_id = auth.uid()
        and wm.role is not null
    ),
    (
      select m.role
      from public.workspaces w
      join public.organization_members m
        on m.organization_id = w.organization_id
      where w.id = p_workspace_id
        and m.user_id = auth.uid()
    )
  );
$$;

-- Does the caller hold a permission in this organisation?
create or replace function app.has_org_permission(
  p_organization_id uuid,
  p_permission app.permission
)
returns boolean
language sql
security definer
set search_path = public, pg_catalog
stable
as $$
  select exists (
    select 1
    from public.organization_members m
    join app.role_permissions rp on rp.role = m.role
    where m.organization_id = p_organization_id
      and m.user_id = auth.uid()
      and rp.permission = p_permission
  );
$$;

-- Does the caller hold a permission in this workspace?
create or replace function app.has_workspace_permission(
  p_workspace_id uuid,
  p_permission app.permission
)
returns boolean
language sql
security definer
set search_path = app, public, pg_catalog
stable
as $$
  select exists (
    select 1
    from app.role_permissions rp
    where rp.role = app.workspace_role(p_workspace_id)
      and rp.permission = p_permission
  );
$$;

-- Owner-only actions: deleting the organisation, transferring ownership,
-- removing an admin. Separated from `admin` deliberately.
create or replace function app.is_org_owner(p_organization_id uuid)
returns boolean
language sql
security definer
set search_path = app, public, pg_catalog
stable
as $$
  select app.org_role(p_organization_id) = 'owner';
$$;

revoke all on function
  app.is_org_member(uuid),
  app.org_role(uuid),
  app.is_workspace_member(uuid),
  app.workspace_role(uuid),
  app.has_org_permission(uuid, app.permission),
  app.has_workspace_permission(uuid, app.permission),
  app.is_org_owner(uuid)
from public;

grant execute on function
  app.is_org_member(uuid),
  app.org_role(uuid),
  app.is_workspace_member(uuid),
  app.workspace_role(uuid),
  app.has_org_permission(uuid, app.permission),
  app.has_workspace_permission(uuid, app.permission),
  app.is_org_owner(uuid)
to authenticated, service_role;

-- =============================================================================
-- INDEXES FOR RLS
--
-- Every column a policy filters on needs an index. Without them each policy
-- evaluation is a sequential scan, and because policies run per candidate row
-- the cost is multiplied by the size of the table being queried — this is the
-- single most common cause of a "Supabase got slow" report.
-- =============================================================================
create index organization_members_user_idx on public.organization_members (user_id);
create index organization_members_org_idx on public.organization_members (organization_id);
create index organization_members_user_org_role_idx
  on public.organization_members (user_id, organization_id, role);
create index workspace_members_user_idx on public.workspace_members (user_id);
create index workspace_members_workspace_idx on public.workspace_members (workspace_id);
-- The `workspace_members_write` policy filters on organization_id, so this is a
-- policy index, not a convenience one. Caught by assertion 4 in 0014.
create index workspace_members_organization_idx on public.workspace_members (organization_id);
create index workspaces_org_idx on public.workspaces (organization_id) where deleted_at is null;
create index organizations_created_by_idx on public.organizations (created_by);

-- =============================================================================
-- ROW LEVEL SECURITY
-- =============================================================================

alter table public.profiles enable row level security;
alter table public.organizations enable row level security;
alter table public.organization_members enable row level security;
alter table public.workspaces enable row level security;
alter table public.workspace_members enable row level security;

-- Force RLS for table owners too, so a definer function or a superuser-owned
-- connection cannot accidentally read across tenants.
alter table public.organizations force row level security;
alter table public.organization_members force row level security;
alter table public.workspaces force row level security;
alter table public.workspace_members force row level security;

-- --- profiles ---------------------------------------------------------------
-- A user reads and writes only their own profile.
--
-- Teammate names are exposed through a narrow view (0003) rather than by
-- widening this policy: "anyone in a shared org may read your profile" also
-- exposes your email and locale to every member of every org you join.
create policy profiles_select_self on public.profiles
  for select to authenticated
  using (id = auth.uid());

create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

-- No INSERT policy: profiles are created only by the bootstrap function (0016),
-- which runs as definer. A client-side insert would let a user forge a profile
-- row for another auth user's id.

-- --- organizations ----------------------------------------------------------
create policy organizations_select_member on public.organizations
  for select to authenticated
  using (app.is_org_member(id) and deleted_at is null);

create policy organizations_update_admin on public.organizations
  for update to authenticated
  using (app.has_org_permission(id, 'team.manage'))
  with check (app.has_org_permission(id, 'team.manage'));

-- Only the owner may soft-delete, and only via update. There is no DELETE
-- policy at all: hard-deleting an organisation would cascade away the usage
-- ledger and publish history that billing disputes depend on.

-- --- organization_members ---------------------------------------------------
-- Members see the roster of organisations they belong to. This is intentional:
-- the team screen needs it, and a member already knows who they work with.
create policy organization_members_select on public.organization_members
  for select to authenticated
  using (app.is_org_member(organization_id));

create policy organization_members_insert on public.organization_members
  for insert to authenticated
  with check (app.has_org_permission(organization_id, 'team.manage'));

create policy organization_members_update on public.organization_members
  for update to authenticated
  using (app.has_org_permission(organization_id, 'team.manage'))
  with check (
    app.has_org_permission(organization_id, 'team.manage')
    -- Only an owner may create or alter another owner, so an admin cannot
    -- promote themselves and then remove the real owner.
    and (role <> 'owner' or app.is_org_owner(organization_id))
  );

create policy organization_members_delete on public.organization_members
  for delete to authenticated
  using (
    -- Leaving under your own steam is always allowed...
    user_id = auth.uid()
    -- ...and removing someone else requires team.manage, with owners removable
    -- only by an owner.
    or (
      app.has_org_permission(organization_id, 'team.manage')
      and (role <> 'owner' or app.is_org_owner(organization_id))
    )
  );

-- --- workspaces -------------------------------------------------------------
create policy workspaces_select on public.workspaces
  for select to authenticated
  using (app.is_workspace_member(id) and deleted_at is null);

create policy workspaces_insert on public.workspaces
  for insert to authenticated
  with check (app.has_org_permission(organization_id, 'workspace.manage'));

create policy workspaces_update on public.workspaces
  for update to authenticated
  using (app.has_workspace_permission(id, 'workspace.manage'))
  with check (app.has_workspace_permission(id, 'workspace.manage'));

-- --- workspace_members ------------------------------------------------------
create policy workspace_members_select on public.workspace_members
  for select to authenticated
  using (app.is_workspace_member(workspace_id));

create policy workspace_members_write on public.workspace_members
  for all to authenticated
  using (app.has_org_permission(organization_id, 'team.manage'))
  with check (app.has_org_permission(organization_id, 'team.manage'));

-- ── 0003_rls_generator.sql ──
-- =============================================================================
-- 0003 — RLS POLICY GENERATOR
--
-- WHY A GENERATOR RATHER THAN EXPLICIT POLICIES
--
-- The schema has ~45 tenant-owned tables. Written out, that is ~180 policies
-- that are textually near-identical. The failure mode of doing it by hand is not
-- verbosity — it is that policy number 137 gets `organization_id` where it
-- needed `workspace_id`, and nothing fails loudly. A silent cross-tenant read is
-- the worst bug this system can have.
--
-- These functions make the standard patterns declarative and identical by
-- construction. The special cases — OAuth tokens, membership tables, the usage
-- ledger, audit logs — still get hand-written policies, because they are the
-- ones where the standard pattern is wrong.
--
-- Every generated policy is inspectable after the fact:
--     select tablename, policyname, cmd, qual from pg_policies
--     where schemaname = 'public' order by tablename;
--
-- and 0017 asserts that no exposed tenant table escaped without RLS.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Workspace-scoped tables: the common case.
--
-- Requires a `workspace_id` column. Read access follows workspace membership;
-- writes require a named permission, so an editor can create content while a
-- reviewer cannot, from the same generated policy set.
-- -----------------------------------------------------------------------------
create or replace function app.apply_workspace_rls(
  p_table regclass,
  p_write_permission app.permission default 'content.create',
  p_delete_permission app.permission default 'assets.delete'
)
returns void
language plpgsql
as $$
declare
  v_table text := p_table::text;
  -- Read the bare table name from the catalogue, NOT from `regclass::text`.
  -- `regclass::text` omits the schema when it is on the search_path, so
  -- `'public.campaigns'::regclass::text` is `campaigns` and a split on '.' yields
  -- an empty string — which silently named every generated index `_workspace_idx`
  -- and collapsed thirty-odd indexes into one. Verified by assertion 4 in 0014.
  v_name  text := (select c.relname from pg_class c where c.oid = p_table);
begin
  -- `format` with %I/%L throughout: these identifiers come from migration code
  -- rather than user input, but a generator that concatenates SQL strings is a
  -- pattern that gets copied to somewhere it does matter.
  execute format('alter table %s enable row level security', v_table);
  execute format('alter table %s force row level security', v_table);

  execute format($f$
    create policy %I on %s
      for select to authenticated
      using (app.is_workspace_member(workspace_id))
  $f$, v_name || '_select', v_table);

  execute format($f$
    create policy %I on %s
      for insert to authenticated
      with check (app.has_workspace_permission(workspace_id, %L))
  $f$, v_name || '_insert', v_table, p_write_permission);

  execute format($f$
    create policy %I on %s
      for update to authenticated
      using (app.has_workspace_permission(workspace_id, %L))
      with check (app.has_workspace_permission(workspace_id, %L))
  $f$, v_name || '_update', v_table, p_write_permission, p_write_permission);

  execute format($f$
    create policy %I on %s
      for delete to authenticated
      using (app.has_workspace_permission(workspace_id, %L))
  $f$, v_name || '_delete', v_table, p_delete_permission);

  -- The index that keeps the SELECT policy off a sequential scan.
  execute format(
    'create index if not exists %I on %s (workspace_id)',
    v_name || '_workspace_idx', v_table
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- Organisation-scoped tables: things that are not per-workspace, such as
-- subscriptions and account groups shared across a client's workspaces.
-- -----------------------------------------------------------------------------
create or replace function app.apply_org_rls(
  p_table regclass,
  p_write_permission app.permission default 'campaign.manage',
  p_delete_permission app.permission default 'assets.delete'
)
returns void
language plpgsql
as $$
declare
  v_table text := p_table::text;
  -- Read the bare table name from the catalogue, NOT from `regclass::text`.
  -- `regclass::text` omits the schema when it is on the search_path, so
  -- `'public.campaigns'::regclass::text` is `campaigns` and a split on '.' yields
  -- an empty string — which silently named every generated index `_workspace_idx`
  -- and collapsed thirty-odd indexes into one. Verified by assertion 4 in 0014.
  v_name  text := (select c.relname from pg_class c where c.oid = p_table);
begin
  execute format('alter table %s enable row level security', v_table);
  execute format('alter table %s force row level security', v_table);

  execute format($f$
    create policy %I on %s
      for select to authenticated
      using (app.is_org_member(organization_id))
  $f$, v_name || '_select', v_table);

  execute format($f$
    create policy %I on %s
      for insert to authenticated
      with check (app.has_org_permission(organization_id, %L))
  $f$, v_name || '_insert', v_table, p_write_permission);

  execute format($f$
    create policy %I on %s
      for update to authenticated
      using (app.has_org_permission(organization_id, %L))
      with check (app.has_org_permission(organization_id, %L))
  $f$, v_name || '_update', v_table, p_write_permission, p_write_permission);

  execute format($f$
    create policy %I on %s
      for delete to authenticated
      using (app.has_org_permission(organization_id, %L))
  $f$, v_name || '_delete', v_table, p_delete_permission);

  execute format(
    'create index if not exists %I on %s (organization_id)',
    v_name || '_organization_idx', v_table
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- Read-only tenant tables: rows the *system* produces and a user may only read.
--
-- Metrics, job events, provider runs, audit entries. Writes come exclusively
-- from workers holding the service-role key, which bypasses RLS. Granting a
-- client INSERT here would let a user fabricate their own analytics.
-- -----------------------------------------------------------------------------
create or replace function app.apply_workspace_readonly_rls(p_table regclass)
returns void
language plpgsql
as $$
declare
  v_table text := p_table::text;
  -- Read the bare table name from the catalogue, NOT from `regclass::text`.
  -- `regclass::text` omits the schema when it is on the search_path, so
  -- `'public.campaigns'::regclass::text` is `campaigns` and a split on '.' yields
  -- an empty string — which silently named every generated index `_workspace_idx`
  -- and collapsed thirty-odd indexes into one. Verified by assertion 4 in 0014.
  v_name  text := (select c.relname from pg_class c where c.oid = p_table);
begin
  execute format('alter table %s enable row level security', v_table);
  execute format('alter table %s force row level security', v_table);

  execute format($f$
    create policy %I on %s
      for select to authenticated
      using (app.is_workspace_member(workspace_id))
  $f$, v_name || '_select', v_table);

  execute format(
    'create index if not exists %I on %s (workspace_id)',
    v_name || '_workspace_idx', v_table
  );
end;
$$;

-- -----------------------------------------------------------------------------
-- Child tables reached through a parent.
--
-- Script segments, storyboard shots, composition tracks and experiment variants
-- carry no tenant column of their own — denormalising one onto every child row
-- creates a second source of truth that can disagree with the parent. Instead
-- the policy joins to the parent and reuses its check.
-- -----------------------------------------------------------------------------
create or replace function app.apply_child_rls(
  p_table regclass,
  p_parent_table text,
  p_fk_column text,
  p_write_permission app.permission default 'content.create'
)
returns void
language plpgsql
as $$
declare
  v_table text := p_table::text;
  -- See the note in app.apply_workspace_rls: never derive this from regclass::text.
  v_name  text := (select c.relname from pg_class c where c.oid = p_table);
  v_visible text;
  v_writable text;
begin
  execute format('alter table %s enable row level security', v_table);
  execute format('alter table %s force row level security', v_table);

  v_visible := format(
    'exists (select 1 from public.%I p where p.id = %I and app.is_workspace_member(p.workspace_id))',
    p_parent_table, p_fk_column
  );
  v_writable := format(
    'exists (select 1 from public.%I p where p.id = %I and app.has_workspace_permission(p.workspace_id, %L))',
    p_parent_table, p_fk_column, p_write_permission
  );

  execute format('create policy %I on %s for select to authenticated using (%s)',
    v_name || '_select', v_table, v_visible);
  execute format('create policy %I on %s for insert to authenticated with check (%s)',
    v_name || '_insert', v_table, v_writable);
  execute format('create policy %I on %s for update to authenticated using (%s) with check (%s)',
    v_name || '_update', v_table, v_writable, v_writable);
  execute format('create policy %I on %s for delete to authenticated using (%s)',
    v_name || '_delete', v_table, v_writable);

  -- The join in every one of those policies runs on this column.
  execute format('create index if not exists %I on %s (%I)',
    v_name || '_' || p_fk_column || '_idx', v_table, p_fk_column);
end;
$$;

comment on function app.apply_workspace_rls is
  'Standard workspace-scoped tenant policies + workspace_id index. See 0003 for why this is generated.';
comment on function app.apply_child_rls is
  'Policies for a child table with no tenant column; authorises via its parent.';

-- ── 0004_brands_onboarding.sql ──
-- =============================================================================
-- 0004 — BRANDS, ONBOARDING, AND THE TEAMMATE VIEW
-- =============================================================================

-- -----------------------------------------------------------------------------
-- BRANDS
-- The identity content is produced for. A workspace may hold several — a media
-- network runs many brands inside one client workspace.
-- -----------------------------------------------------------------------------
create table public.brands (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  name text not null check (length(trim(name)) between 1 and 120),
  website_url text check (website_url is null or website_url ~ '^https?://'),
  description text,
  industry text,
  primary_language text not null default 'en',
  -- Onboarding creates a placeholder brand so the dashboard is never empty of
  -- context. This flag is what lets the UI prompt the user to complete it
  -- instead of presenting an unnamed brand as configured.
  is_placeholder boolean not null default false,
  is_default boolean not null default false,
  deleted_at timestamptz,
  created_by uuid not null references auth.users (id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.brands');
select app.apply_workspace_rls('public.brands', 'campaign.manage', 'assets.delete');

create unique index brands_one_default_per_workspace
  on public.brands (workspace_id)
  where is_default and deleted_at is null;

-- -----------------------------------------------------------------------------
-- BRAND PROFILES
-- Voice and audience, split from `brands` because it is large, optional, and
-- rewritten by the AI brief step independently of the brand's identity.
-- -----------------------------------------------------------------------------
create table public.brand_profiles (
  id uuid primary key default extensions.gen_random_uuid(),
  brand_id uuid not null unique references public.brands (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  target_audience text,
  tone text,
  primary_objective text,
  value_propositions text[] not null default '{}',
  content_pillars text[] not null default '{}',
  banned_topics text[] not null default '{}',
  -- Words the brand must never use. Enforced at generation time, which is why it
  -- is a first-class column rather than buried in a settings blob.
  banned_phrases text[] not null default '{}',
  visual_style text,
  colour_tokens jsonb not null default '{}'::jsonb,
  logo_asset_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.brand_profiles');
select app.apply_workspace_rls('public.brand_profiles', 'campaign.manage', 'assets.delete');

-- -----------------------------------------------------------------------------
-- ONBOARDING PROGRESS
-- One row per user per organisation. Step data is kept so a user who abandons
-- onboarding halfway resumes rather than restarting.
-- -----------------------------------------------------------------------------
create table public.onboarding_progress (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  current_step smallint not null default 1 check (current_step between 1 and 7),
  completed_steps smallint[] not null default '{}',
  account_type text check (account_type in ('personal', 'agency', 'company', 'network')),
  content_goals text[] not null default '{}',
  preferred_formats text[] not null default '{}',
  first_campaign_prompt text,
  completed_at timestamptz,
  skipped_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (organization_id, user_id)
);

select app.attach_touch_trigger('public.onboarding_progress');

alter table public.onboarding_progress enable row level security;
alter table public.onboarding_progress force row level security;

-- Onboarding is personal: a teammate's answers are not the caller's business,
-- so this is scoped to the user, not the organisation.
create policy onboarding_progress_own on public.onboarding_progress
  for all to authenticated
  using (user_id = auth.uid() and app.is_org_member(organization_id))
  with check (user_id = auth.uid() and app.is_org_member(organization_id));

create index onboarding_progress_user_idx on public.onboarding_progress (user_id);

-- -----------------------------------------------------------------------------
-- TEAMMATE VIEW
--
-- `profiles` is readable only by its owner. The team screen and every "created
-- by" byline still need a name and an avatar for colleagues.
--
-- This view is deliberately NOT `security_invoker`. With invoker rights the
-- `profiles` policy (`id = auth.uid()`) would restrict it to the caller's own
-- row, which is useless for a roster. It therefore runs with the view owner's
-- rights and does its own authorisation in the WHERE clause.
--
-- That places the whole burden on the predicate below, so it is deliberately
-- narrow on both axes:
--   - columns: name, avatar and role only. Never email, locale, timezone or
--     notification preferences.
--   - rows: `app.is_org_member` restricts to organisations the caller belongs
--     to. Because owner rights also bypass RLS on organization_members, this
--     predicate is the only thing standing between the caller and every user in
--     the database — it must never be removed or widened.
-- -----------------------------------------------------------------------------
create view public.organization_teammates as
select
  m.organization_id,
  m.user_id,
  m.role,
  m.accepted_at,
  p.full_name,
  p.avatar_url
from public.organization_members m
join public.profiles p on p.id = m.user_id
where app.is_org_member(m.organization_id);

comment on view public.organization_teammates is
  'Name, avatar and role of co-members only. Runs with owner rights and authorises via app.is_org_member in its WHERE clause — see 0004 before editing.';

grant select on public.organization_teammates to authenticated;

-- ── 0005_campaigns.sql ──
-- =============================================================================
-- 0005 — CAMPAIGNS
--
-- A campaign is the parent object for generation, publishing and analytics. The
-- ten pipeline stages are modelled as a status column plus a per-stage progress
-- table, not as a single "stage" integer: stages can be blocked independently
-- and a blocked stage needs a reason attached to it.
-- =============================================================================

create type app.campaign_stage as enum (
  'brief',
  'concepts',
  'scripts',
  'storyboards',
  'assets',
  'editing',
  'approval',
  'schedule',
  'publish',
  'learn'
);

create type app.stage_state as enum (
  'pending',
  'active',
  'complete',
  'blocked',
  'skipped'
);

create type app.generation_mode as enum (
  'quick',
  'campaign',
  'repurpose',
  'product',
  'account_launch',
  'batch_studio'
);

create table public.campaigns (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  brand_id uuid references public.brands (id) on delete set null,

  name text not null check (length(trim(name)) between 1 and 200),
  objective text,
  mode app.generation_mode not null default 'campaign',
  status app.review_status not null default 'draft',

  -- Scheduling window. Checked rather than trusted: an inverted range silently
  -- produces a publish plan with no slots in it.
  starts_on date,
  ends_on date,
  constraint campaigns_date_range check (ends_on is null or starts_on is null or ends_on >= starts_on),

  languages text[] not null default '{en}',
  platforms app.platform[] not null default '{}',

  -- Denormalised counters, maintained by the job workers. Present so the campaign
  -- list can render progress without an aggregate over content_items per row —
  -- with 100 campaigns that is 100 subqueries per page load.
  concepts_count integer not null default 0 check (concepts_count >= 0),
  content_count integer not null default 0 check (content_count >= 0),
  published_count integer not null default 0 check (published_count >= 0),

  -- Cost accounting in integer minor units. Never floats: repeated float
  -- addition across thousands of generation runs accumulates visible error, and
  -- this figure is shown to users as money.
  estimated_cost_cents integer not null default 0 check (estimated_cost_cents >= 0),
  actual_cost_cents integer not null default 0 check (actual_cost_cents >= 0),

  archived_at timestamptz,
  deleted_at timestamptz,
  created_by uuid not null references auth.users (id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.campaigns');
select app.apply_workspace_rls('public.campaigns', 'campaign.manage', 'assets.delete');

create index campaigns_workspace_status_idx
  on public.campaigns (workspace_id, status, created_at desc)
  where deleted_at is null;
create index campaigns_brand_idx on public.campaigns (brand_id) where deleted_at is null;
-- Trigram index for the command palette's campaign search.
create index campaigns_name_trgm_idx on public.campaigns using gin (name extensions.gin_trgm_ops);

-- -----------------------------------------------------------------------------
-- CAMPAIGN BRIEFS
--
-- The structured brief derived from the user's prompt. Versioned rather than
-- updated in place: regenerating from an edited brief must not destroy the
-- record of what produced the content that already exists.
-- -----------------------------------------------------------------------------
create table public.campaign_briefs (
  id uuid primary key default extensions.gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  version integer not null default 1 check (version >= 1),

  raw_prompt text,
  -- Where the input came from: a URL, an upload, a library asset.
  source_kind text check (source_kind in ('prompt', 'website', 'product', 'document', 'video', 'audio', 'image', 'library')),
  source_url text,
  source_asset_id uuid,

  -- Structured output of the brief stage.
  audience text,
  tone text,
  key_messages text[] not null default '{}',
  content_pillars text[] not null default '{}',
  call_to_action text,

  -- Imported website and document text is untrusted input that will be placed in
  -- an LLM prompt. This flag records that the sanitiser ran, so a later
  -- generation step can refuse to proceed on unsanitised text rather than
  -- assuming it was handled upstream.
  external_text_sanitised boolean not null default false,

  is_current boolean not null default true,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (campaign_id, version)
);

select app.attach_touch_trigger('public.campaign_briefs');
select app.apply_workspace_rls('public.campaign_briefs', 'campaign.manage', 'assets.delete');

create unique index campaign_briefs_one_current
  on public.campaign_briefs (campaign_id)
  where is_current;

-- -----------------------------------------------------------------------------
-- CAMPAIGN STAGE PROGRESS
-- One row per stage per campaign, so the pipeline visual reads real state and a
-- blocked stage carries its reason.
-- -----------------------------------------------------------------------------
create table public.campaign_stages (
  id uuid primary key default extensions.gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  stage app.campaign_stage not null,
  state app.stage_state not null default 'pending',
  blocked_reason text,
  started_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (campaign_id, stage),
  -- A blocked stage without a reason produces the "Something went wrong" screen
  -- the brief forbids, so the database refuses to store one.
  constraint campaign_stages_blocked_needs_reason
    check (state <> 'blocked' or blocked_reason is not null)
);

select app.attach_touch_trigger('public.campaign_stages');
select app.apply_workspace_rls('public.campaign_stages', 'campaign.manage', 'assets.delete');

-- -----------------------------------------------------------------------------
-- CAMPAIGN TARGETS
-- Which platforms and which authorised accounts a campaign publishes to.
-- -----------------------------------------------------------------------------
create table public.campaign_platforms (
  id uuid primary key default extensions.gen_random_uuid(),
  campaign_id uuid not null references public.campaigns (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  platform app.platform not null,
  aspect_ratios app.aspect_ratio[] not null default '{9:16}',
  created_at timestamptz not null default now(),
  unique (campaign_id, platform)
);

select app.apply_workspace_rls('public.campaign_platforms', 'campaign.manage', 'assets.delete');

-- ── 0006_content.sql ──
-- =============================================================================
-- 0006 — CONTENT
--
-- concepts → hooks → content items → variants, plus scripts, storyboards and
-- shots.
--
-- The shape that matters: a *variant* is the unit that gets published, and it
-- carries its own platform, ratio, language and account. That is what makes
-- "100 videos across 4 platforms in 3 languages" a row count rather than a
-- special case, and what lets the duplicate-content check compare real records.
-- =============================================================================

create table public.content_concepts (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  campaign_id uuid not null references public.campaigns (id) on delete cascade,

  position integer not null default 0,
  title text not null,
  angle text,
  summary text,
  status app.review_status not null default 'draft',

  -- Records whether a real provider or the mock produced this. Read by every
  -- surface that must decide whether to show the "Demo data" label.
  origin app.output_origin not null default 'mock',

  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.content_concepts');
select app.apply_workspace_rls('public.content_concepts', 'content.create', 'content.delete');

create index content_concepts_campaign_idx
  on public.content_concepts (campaign_id, position);

-- -----------------------------------------------------------------------------
-- HOOKS
-- The first 1–3 seconds. Separated from the concept because hook performance is
-- compared across variants in the experiments module — it needs its own identity
-- and its own metrics, not a string on a parent row.
-- -----------------------------------------------------------------------------
create table public.content_hooks (
  id uuid primary key default extensions.gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  concept_id uuid not null references public.content_concepts (id) on delete cascade,
  label text not null,
  text text not null,
  position integer not null default 0,
  origin app.output_origin not null default 'mock',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.content_hooks');
select app.apply_workspace_rls('public.content_hooks', 'content.create', 'content.delete');

create index content_hooks_concept_idx on public.content_hooks (concept_id, position);

-- -----------------------------------------------------------------------------
-- CONTENT ITEMS
-- One creative idea in one language: the thing an editor opens in the studio.
-- Platform-specific renditions of it are `content_variants`.
-- -----------------------------------------------------------------------------
create table public.content_items (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  campaign_id uuid references public.campaigns (id) on delete set null,
  concept_id uuid references public.content_concepts (id) on delete set null,
  hook_id uuid references public.content_hooks (id) on delete set null,
  brand_id uuid references public.brands (id) on delete set null,

  title text not null default 'Untitled',
  content_type text not null default 'short_video'
    check (content_type in ('short_video', 'long_video', 'image', 'carousel', 'text')),
  language text not null default 'en',
  status app.review_status not null default 'draft',

  -- Canonical duration in milliseconds. Integer, because seconds-as-float turns
  -- frame-accurate trim points into off-by-one rendering bugs.
  duration_ms integer check (duration_ms is null or duration_ms > 0),

  caption text,
  call_to_action text,

  origin app.output_origin not null default 'mock',

  -- Optimistic-concurrency token for the studio's autosave. Incremented by the
  -- application on each save; a mismatch means another editor saved first and the
  -- client must reconcile rather than silently overwrite.
  revision integer not null default 1 check (revision >= 1),

  approved_at timestamptz,
  approved_by uuid references auth.users (id) on delete set null,
  deleted_at timestamptz,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.content_items');
select app.apply_workspace_rls('public.content_items', 'content.create', 'content.delete');

create index content_items_workspace_status_idx
  on public.content_items (workspace_id, status, updated_at desc)
  where deleted_at is null;
create index content_items_campaign_idx on public.content_items (campaign_id) where deleted_at is null;
create index content_items_concept_idx on public.content_items (concept_id);

-- -----------------------------------------------------------------------------
-- CONTENT VARIANTS
-- The publishable unit: this item, recomposed for one platform at one ratio for
-- one account.
-- -----------------------------------------------------------------------------
create table public.content_variants (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  content_item_id uuid not null references public.content_items (id) on delete cascade,

  platform app.platform not null,
  aspect_ratio app.aspect_ratio not null default '9:16',
  width integer check (width is null or width > 0),
  height integer check (height is null or height > 0),
  language text not null default 'en',

  -- Per-platform overrides. Null means "inherit from the content item", so a
  -- caption edited for TikTok does not silently change the Instagram post.
  caption_override text,
  title_override text,
  call_to_action_override text,

  -- Format adaptation is never a blind centre crop. These carry the per-ratio
  -- layout decisions: subject focus, safe-area insets, text and CTA placement.
  layout_overrides jsonb not null default '{}'::jsonb,

  rendered_asset_id uuid,
  thumbnail_asset_id uuid,

  status app.review_status not null default 'draft',
  origin app.output_origin not null default 'mock',

  -- Content fingerprint over the rendered media, used by the duplicate-content
  -- warning before a batch publish. Nullable because it only exists post-render.
  content_hash text,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- One variant per item per platform/ratio/language. This is what makes a
  -- retried batch-generation job idempotent instead of producing duplicates.
  unique (content_item_id, platform, aspect_ratio, language)
);

select app.attach_touch_trigger('public.content_variants');
select app.apply_workspace_rls('public.content_variants', 'content.create', 'content.delete');

create index content_variants_item_idx on public.content_variants (content_item_id);
create index content_variants_platform_idx on public.content_variants (workspace_id, platform, status);
-- Powers the duplicate-asset warning.
create index content_variants_hash_idx on public.content_variants (workspace_id, content_hash)
  where content_hash is not null;

-- -----------------------------------------------------------------------------
-- SCRIPTS AND SEGMENTS
-- Segmented so a single shot can be regenerated without touching the rest — the
-- brief's requirement that changing one shot must not regenerate the campaign.
-- -----------------------------------------------------------------------------
create table public.scripts (
  id uuid primary key default extensions.gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  content_item_id uuid not null references public.content_items (id) on delete cascade,
  version integer not null default 1 check (version >= 1),
  is_current boolean not null default true,
  full_text text,
  word_count integer,
  origin app.output_origin not null default 'mock',
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (content_item_id, version)
);

select app.attach_touch_trigger('public.scripts');
select app.apply_workspace_rls('public.scripts', 'content.create', 'content.delete');

create unique index scripts_one_current on public.scripts (content_item_id) where is_current;

create table public.script_segments (
  id uuid primary key default extensions.gen_random_uuid(),
  script_id uuid not null references public.scripts (id) on delete cascade,
  position integer not null,
  role text not null default 'body' check (role in ('hook', 'body', 'cta', 'outro')),
  text text not null,
  start_ms integer check (start_ms is null or start_ms >= 0),
  end_ms integer check (end_ms is null or end_ms >= 0),
  constraint script_segments_time_order check (end_ms is null or start_ms is null or end_ms > start_ms),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (script_id, position)
);

select app.attach_touch_trigger('public.script_segments');
-- No tenant column: authorised through the parent script. See 0003.
select app.apply_child_rls('public.script_segments', 'scripts', 'script_id', 'content.create');

-- -----------------------------------------------------------------------------
-- STORYBOARDS AND SHOTS
-- -----------------------------------------------------------------------------
create table public.storyboards (
  id uuid primary key default extensions.gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  content_item_id uuid not null references public.content_items (id) on delete cascade,
  version integer not null default 1 check (version >= 1),
  is_current boolean not null default true,
  origin app.output_origin not null default 'mock',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (content_item_id, version)
);

select app.attach_touch_trigger('public.storyboards');
select app.apply_workspace_rls('public.storyboards', 'content.create', 'content.delete');

create unique index storyboards_one_current on public.storyboards (content_item_id) where is_current;

create table public.shots (
  id uuid primary key default extensions.gen_random_uuid(),
  storyboard_id uuid not null references public.storyboards (id) on delete cascade,
  script_segment_id uuid references public.script_segments (id) on delete set null,
  position integer not null,
  description text,
  visual_prompt text,
  camera text,
  duration_ms integer check (duration_ms is null or duration_ms > 0),
  -- Per-shot media, so regenerating one shot replaces one asset.
  asset_id uuid,
  status app.job_status not null default 'pending',
  origin app.output_origin not null default 'mock',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (storyboard_id, position)
);

select app.attach_touch_trigger('public.shots');
select app.apply_child_rls('public.shots', 'storyboards', 'storyboard_id', 'content.create');

-- ── 0007_media_generation.sql ──
-- =============================================================================
-- 0007 — MEDIA, COMPOSITIONS, GENERATION
--
-- The rule this file exists to enforce: never store only a final MP4. A
-- composition — tracks, clips, captions, timings — is what makes a 4:5 variant
-- derivable from a 9:16 one. Without it, "adapt this to another format" degrades
-- into a centre crop, which is the thing the product is supposed to be better
-- than.
-- =============================================================================

create table public.media_assets (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  brand_id uuid references public.brands (id) on delete set null,
  campaign_id uuid references public.campaigns (id) on delete set null,
  content_item_id uuid references public.content_items (id) on delete set null,

  kind app.asset_kind not null,

  -- Storage location. `storage_path` is the object key inside the bucket; access
  -- is always via a short-lived signed URL, never a public URL. A permanent
  -- public URL on private user media leaks it to anyone who has ever seen it.
  bucket text not null check (bucket in ('source-media', 'generated-media', 'brand-assets', 'avatars', 'exports')),
  storage_path text not null,

  filename text,
  mime_type text,
  byte_size bigint check (byte_size is null or byte_size >= 0),
  duration_ms integer check (duration_ms is null or duration_ms >= 0),
  width integer check (width is null or width > 0),
  height integer check (height is null or height > 0),
  aspect_ratio app.aspect_ratio,
  codec text,
  -- Poster image for video, so a library grid never attaches a <video> element
  -- per tile just to show a still frame.
  poster_asset_id uuid references public.media_assets (id) on delete set null,

  origin app.output_origin not null default 'user_upload',
  provider text,
  provider_model text,
  generation_cost_cents integer not null default 0 check (generation_cost_cents >= 0),

  -- Deduplication and the duplicate-content warning.
  checksum text,

  -- Upload lifecycle. A row exists before the bytes land, so an interrupted
  -- upload is visible and cleanable rather than an orphaned object.
  upload_state text not null default 'pending'
    check (upload_state in ('pending', 'uploaded', 'processing', 'ready', 'failed')),
  scan_state text not null default 'pending'
    check (scan_state in ('pending', 'clean', 'rejected', 'skipped')),

  deleted_at timestamptz,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- One row per object. Makes a retried upload idempotent.
  unique (bucket, storage_path)
);

select app.attach_touch_trigger('public.media_assets');
select app.apply_workspace_rls('public.media_assets', 'content.create', 'assets.delete');

create index media_assets_workspace_kind_idx
  on public.media_assets (workspace_id, kind, created_at desc)
  where deleted_at is null;
create index media_assets_campaign_idx on public.media_assets (campaign_id) where deleted_at is null;
create index media_assets_checksum_idx on public.media_assets (workspace_id, checksum)
  where checksum is not null;

-- Deferred FKs for the columns that pointed at media_assets before it existed.
alter table public.brand_profiles
  add constraint brand_profiles_logo_fk
  foreign key (logo_asset_id) references public.media_assets (id) on delete set null;

alter table public.campaign_briefs
  add constraint campaign_briefs_source_asset_fk
  foreign key (source_asset_id) references public.media_assets (id) on delete set null;

alter table public.content_variants
  add constraint content_variants_rendered_fk
  foreign key (rendered_asset_id) references public.media_assets (id) on delete set null;

alter table public.content_variants
  add constraint content_variants_thumbnail_fk
  foreign key (thumbnail_asset_id) references public.media_assets (id) on delete set null;

alter table public.shots
  add constraint shots_asset_fk
  foreign key (asset_id) references public.media_assets (id) on delete set null;

-- -----------------------------------------------------------------------------
-- ASSET VERSIONS
-- Regeneration produces a new version rather than overwriting. Overwriting makes
-- "undo" impossible and breaks any published post already pointing at the object.
-- -----------------------------------------------------------------------------
create table public.media_asset_versions (
  id uuid primary key default extensions.gen_random_uuid(),
  asset_id uuid not null references public.media_assets (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  version integer not null check (version >= 1),
  storage_path text not null,
  byte_size bigint,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  unique (asset_id, version)
);

select app.apply_workspace_rls('public.media_asset_versions', 'content.create', 'assets.delete');

-- -----------------------------------------------------------------------------
-- COMPOSITIONS
-- The canonical timeline. Renderer-agnostic by design so the same document can
-- drive Remotion, raw FFmpeg or an external render worker.
-- -----------------------------------------------------------------------------
create table public.compositions (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  content_item_id uuid references public.content_items (id) on delete cascade,
  content_variant_id uuid references public.content_variants (id) on delete cascade,

  width integer not null check (width > 0),
  height integer not null check (height > 0),
  fps integer not null default 30 check (fps between 1 and 120),
  -- Frames, not seconds. The renderer works in frames, and storing seconds
  -- reintroduces rounding at every conversion.
  duration_frames integer not null check (duration_frames > 0),
  background_colour text,

  revision integer not null default 1 check (revision >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Belongs to an item or a variant, never both and never neither: an orphan
  -- composition is unreachable, and one attached to both has no clear owner.
  constraint compositions_single_owner check (
    (content_item_id is not null and content_variant_id is null)
    or (content_item_id is null and content_variant_id is not null)
  )
);

select app.attach_touch_trigger('public.compositions');
select app.apply_workspace_rls('public.compositions', 'content.create', 'content.delete');

create table public.composition_tracks (
  id uuid primary key default extensions.gen_random_uuid(),
  composition_id uuid not null references public.compositions (id) on delete cascade,
  kind text not null check (kind in ('video', 'audio', 'voice', 'music', 'text', 'caption', 'overlay')),
  position integer not null,
  is_muted boolean not null default false,
  is_locked boolean not null default false,
  created_at timestamptz not null default now(),
  unique (composition_id, position)
);

alter table public.composition_tracks enable row level security;
alter table public.composition_tracks force row level security;

-- Two levels down from a workspace, so the check joins through compositions.
create policy composition_tracks_select on public.composition_tracks
  for select to authenticated
  using (exists (
    select 1 from public.compositions c
    where c.id = composition_id and app.is_workspace_member(c.workspace_id)
  ));

create policy composition_tracks_write on public.composition_tracks
  for all to authenticated
  using (exists (
    select 1 from public.compositions c
    where c.id = composition_id
      and app.has_workspace_permission(c.workspace_id, 'content.create')
  ))
  with check (exists (
    select 1 from public.compositions c
    where c.id = composition_id
      and app.has_workspace_permission(c.workspace_id, 'content.create')
  ));

create index composition_tracks_composition_idx on public.composition_tracks (composition_id);

create table public.composition_clips (
  id uuid primary key default extensions.gen_random_uuid(),
  track_id uuid not null references public.composition_tracks (id) on delete cascade,
  asset_id uuid references public.media_assets (id) on delete set null,
  position integer not null,
  -- All timings in frames, consistent with the composition.
  start_frame integer not null check (start_frame >= 0),
  duration_frames integer not null check (duration_frames > 0),
  -- Trim points within the source asset.
  source_in_frame integer check (source_in_frame is null or source_in_frame >= 0),
  source_out_frame integer,
  text_content text,
  style jsonb not null default '{}'::jsonb,
  transform jsonb not null default '{}'::jsonb,
  transition_in text,
  transition_out text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (track_id, position),
  constraint composition_clips_source_range
    check (source_out_frame is null or source_in_frame is null or source_out_frame > source_in_frame)
);

select app.attach_touch_trigger('public.composition_clips');

alter table public.composition_clips enable row level security;
alter table public.composition_clips force row level security;

-- Three levels from a workspace: clip → track → composition. `app.apply_child_rls`
-- cannot be used here — it assumes the parent carries `workspace_id`, and
-- `composition_tracks` does not, so the generated policy would reference a column
-- that does not exist. Denormalising `workspace_id` onto clips was the
-- alternative and was rejected: it creates a second source of truth that a
-- re-parented clip can silently contradict.
create policy composition_clips_select on public.composition_clips
  for select to authenticated
  using (exists (
    select 1
    from public.composition_tracks t
    join public.compositions c on c.id = t.composition_id
    where t.id = track_id and app.is_workspace_member(c.workspace_id)
  ));

create policy composition_clips_write on public.composition_clips
  for all to authenticated
  using (exists (
    select 1
    from public.composition_tracks t
    join public.compositions c on c.id = t.composition_id
    where t.id = track_id
      and app.has_workspace_permission(c.workspace_id, 'content.create')
  ))
  with check (exists (
    select 1
    from public.composition_tracks t
    join public.compositions c on c.id = t.composition_id
    where t.id = track_id
      and app.has_workspace_permission(c.workspace_id, 'content.create')
  ));

-- The join column in every policy above.
create index composition_clips_track_idx on public.composition_clips (track_id);

-- -----------------------------------------------------------------------------
-- GENERATION RUNS
--
-- One row per provider call. The brief requires provider, model, prompt version,
-- status, duration, cost and retry count recorded for every generation — this is
-- that record, and it is what makes "were credits charged for this failure?"
-- answerable instead of a guess.
-- -----------------------------------------------------------------------------
create table public.generation_runs (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  campaign_id uuid references public.campaigns (id) on delete set null,
  content_item_id uuid references public.content_items (id) on delete set null,
  content_variant_id uuid references public.content_variants (id) on delete set null,
  shot_id uuid references public.shots (id) on delete set null,

  stage text not null check (stage in (
    'brief', 'strategy', 'concepts', 'hooks', 'script', 'storyboard',
    'image', 'video', 'voice', 'composition', 'adaptation', 'moderation', 'thumbnail'
  )),

  provider text not null,
  provider_model text,
  -- Which prompt template produced this. Without it, a quality regression after a
  -- prompt change is untraceable.
  prompt_version text,
  capability text,

  status app.job_status not null default 'pending',
  attempt integer not null default 1 check (attempt >= 1),

  -- Whether this run was real or the deterministic mock. Anything derived from a
  -- mock run must never be presented as a real generation.
  origin app.output_origin not null default 'mock',

  input_digest text,
  output_summary jsonb,

  started_at timestamptz,
  completed_at timestamptz,
  duration_ms integer check (duration_ms is null or duration_ms >= 0),

  cost_cents integer not null default 0 check (cost_cents >= 0),
  -- Distinguishes "failed and you were charged" from "failed for free", which
  -- the error UI is required to state.
  cost_incurred boolean not null default false,

  failure_code text,
  failure_message text,

  -- Support identifier surfaced in the error UI so a user can quote something
  -- short instead of a UUID.
  reference text not null default upper(substr(replace(extensions.gen_random_uuid()::text, '-', ''), 1, 10)),

  external_job_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.generation_runs');
-- System-written: workers create these with the service-role key. A client that
-- could insert here could fabricate cost and provenance records.
select app.apply_workspace_readonly_rls('public.generation_runs');

create index generation_runs_workspace_created_idx
  on public.generation_runs (workspace_id, created_at desc);
create index generation_runs_status_idx on public.generation_runs (status)
  where status in ('pending', 'queued', 'running', 'waiting_external');
create index generation_runs_item_idx on public.generation_runs (content_item_id);
create unique index generation_runs_reference_idx on public.generation_runs (reference);

-- ── 0008_accounts.sql ──
-- =============================================================================
-- 0008 — CONNECTED ACCOUNTS
--
-- The security-critical file. Two rules shape it:
--
-- 1. OAuth tokens live in a SEPARATE table with NO select policy for
--    authenticated users. Not "a restrictive policy" — none at all. A token for
--    an Instagram professional account is the ability to post as that brand; a
--    read of it through the REST API by a compromised browser session would be
--    an account takeover, not a data leak. Only the service role touches it.
--
-- 2. No password column exists anywhere, and none may be added. Virally connects
--    accounts through official authorisation flows and never asks for social
--    credentials. Enforced by 0014's assertion, so a future migration adding one
--    fails the migration run.
-- =============================================================================

create table public.connected_accounts (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  brand_id uuid references public.brands (id) on delete set null,

  platform app.platform not null,
  -- The platform's own identifier. Unique per platform per workspace so
  -- reconnecting the same account updates rather than duplicating it.
  external_id text not null,
  username text,
  display_name text,
  avatar_url text,
  profile_url text,

  -- Instagram distinguishes personal from professional accounts, and only
  -- professional accounts can be published to via the official API. Storing the
  -- type is what lets the UI explain *why* publishing is unavailable.
  account_kind text check (account_kind in ('personal', 'creator', 'business', 'page', 'channel')),

  health app.connection_health not null default 'healthy',
  health_detail text,

  -- Capabilities actually granted by this connection, resolved at connect time
  -- from the scopes the user consented to. Data-driven, never assumed: the same
  -- platform grants different capabilities to different account types.
  granted_capabilities text[] not null default '{}',
  granted_scopes text[] not null default '{}',

  follower_count integer check (follower_count is null or follower_count >= 0),
  last_synced_at timestamptz,
  last_published_at timestamptz,

  connected_by uuid references auth.users (id) on delete set null,
  connected_at timestamptz not null default now(),
  disconnected_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (workspace_id, platform, external_id)
);

select app.attach_touch_trigger('public.connected_accounts');

alter table public.connected_accounts enable row level security;
alter table public.connected_accounts force row level security;

-- Readable by workspace members: the accounts screen needs it, and it holds no
-- secrets — those are in oauth_connections.
create policy connected_accounts_select on public.connected_accounts
  for select to authenticated
  using (app.is_workspace_member(workspace_id));

-- No INSERT policy. Accounts are created only by the OAuth callback running as
-- the service role, because creating one requires storing a token the client must
-- never handle.

-- A user may rename or reassign an account, and may disconnect it, but the
-- identity columns are set by the platform.
create policy connected_accounts_update on public.connected_accounts
  for update to authenticated
  using (app.has_workspace_permission(workspace_id, 'accounts.connect'))
  with check (app.has_workspace_permission(workspace_id, 'accounts.connect'));

create policy connected_accounts_delete on public.connected_accounts
  for delete to authenticated
  using (app.has_workspace_permission(workspace_id, 'accounts.disconnect'));

create index connected_accounts_workspace_idx on public.connected_accounts (workspace_id)
  where disconnected_at is null;
create index connected_accounts_health_idx on public.connected_accounts (workspace_id, health)
  where disconnected_at is null;
create index connected_accounts_brand_idx on public.connected_accounts (brand_id);

-- -----------------------------------------------------------------------------
-- OAUTH CONNECTIONS — SECRETS. NO CLIENT ACCESS.
-- -----------------------------------------------------------------------------
create table public.oauth_connections (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  connected_account_id uuid not null unique
    references public.connected_accounts (id) on delete cascade,

  platform app.platform not null,

  -- Encrypted at the application layer before insert, with a key held only in
  -- the server environment (TOKEN_ENCRYPTION_KEY). Column-level encryption on top
  -- of RLS means a database backup leak is not immediately a token leak.
  access_token_encrypted text not null,
  refresh_token_encrypted text,
  -- Identifies which key version encrypted this row, so keys can be rotated
  -- without decrypting everything at once.
  encryption_key_id text not null default 'v1',

  token_type text,
  scopes text[] not null default '{}',
  expires_at timestamptz,
  refresh_expires_at timestamptz,
  last_refreshed_at timestamptz,
  refresh_failure_count integer not null default 0 check (refresh_failure_count >= 0),

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.oauth_connections');

alter table public.oauth_connections enable row level security;
alter table public.oauth_connections force row level security;

-- DELIBERATELY NO POLICIES.
--
-- RLS enabled with zero policies denies every operation to `authenticated` and
-- `anon`. The service role bypasses RLS, so workers and the OAuth callback still
-- work. Do not add a select policy here: there is no legitimate reason for a
-- browser to read a platform access token, and the accounts UI reads
-- `connected_account_token_status` below instead.

revoke all on public.oauth_connections from anon, authenticated;

create index oauth_connections_expiry_idx on public.oauth_connections (expires_at)
  where expires_at is not null;

-- -----------------------------------------------------------------------------
-- TOKEN STATUS VIEW
--
-- The UI needs to show "reconnection required" without reading the token. This
-- exposes expiry state and nothing else — no ciphertext, no scopes-as-secrets,
-- no key id. Owner rights with an explicit membership predicate, same pattern and
-- same caveat as the teammate view in 0004.
-- -----------------------------------------------------------------------------
create view public.connected_account_token_status as
select
  c.id as connected_account_id,
  c.workspace_id,
  c.platform,
  o.expires_at,
  o.last_refreshed_at,
  o.refresh_failure_count,
  (o.refresh_token_encrypted is not null) as can_refresh,
  case
    when o.expires_at is null then 'unknown'
    when o.expires_at <= now() then 'expired'
    when o.expires_at <= now() + interval '7 days' then 'expiring_soon'
    else 'valid'
  end as token_state
from public.connected_accounts c
join public.oauth_connections o on o.connected_account_id = c.id
where app.is_workspace_member(c.workspace_id);

comment on view public.connected_account_token_status is
  'Token expiry state for the accounts UI. Never exposes token material. See 0008.';

grant select on public.connected_account_token_status to authenticated;

-- -----------------------------------------------------------------------------
-- ACCOUNT GROUPS
-- Publishing to "all Spanish accounts" as one action, with the membership shown
-- explicitly before anything is scheduled.
-- -----------------------------------------------------------------------------
create table public.account_groups (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  name text not null check (length(trim(name)) between 1 and 120),
  grouping_kind text check (grouping_kind in
    ('brand', 'language', 'country', 'niche', 'client', 'campaign', 'strategy')),
  description text,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, name)
);

select app.attach_touch_trigger('public.account_groups');
select app.apply_workspace_rls('public.account_groups', 'accounts.connect', 'accounts.disconnect');

create table public.account_group_members (
  id uuid primary key default extensions.gen_random_uuid(),
  account_group_id uuid not null references public.account_groups (id) on delete cascade,
  connected_account_id uuid not null references public.connected_accounts (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (account_group_id, connected_account_id)
);

select app.apply_workspace_rls('public.account_group_members', 'accounts.connect', 'accounts.disconnect');

-- -----------------------------------------------------------------------------
-- PLATFORM CAPABILITIES
--
-- Reference data, not tenant data: what each platform permits, per account kind.
-- Readable by every authenticated user, writable by nobody through the API.
--
-- A table rather than a constant in code because these change when a platform
-- changes its API, and the honest UI states ("requires app review", "max 60s")
-- must be updatable without a deploy.
-- -----------------------------------------------------------------------------
create table public.platform_capabilities (
  id uuid primary key default extensions.gen_random_uuid(),
  platform app.platform not null,
  account_kind text not null,
  capability text not null,
  is_supported boolean not null default false,
  requires_app_review boolean not null default false,
  max_duration_seconds integer,
  max_file_size_mb integer,
  supported_ratios app.aspect_ratio[] not null default '{}',
  notes text,
  updated_at timestamptz not null default now(),
  unique (platform, account_kind, capability)
);

select app.attach_touch_trigger('public.platform_capabilities');

alter table public.platform_capabilities enable row level security;

create policy platform_capabilities_read on public.platform_capabilities
  for select to authenticated using (true);

-- No write policies: seeded by migration, updated by migration.

-- -----------------------------------------------------------------------------
-- ACCOUNT LAUNCH KITS
--
-- Generated launch material for an account the user will create *themselves* on
-- the platform. The `manual_checklist` column is the point: this product prepares
-- material, and a human performs the account creation through the platform's own
-- signup. Nothing here automates that, and nothing may be added that does.
-- -----------------------------------------------------------------------------
create table public.account_launch_kits (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  brand_id uuid references public.brands (id) on delete set null,

  target_platform app.platform not null,
  concept text,
  suggested_names text[] not null default '{}',
  suggested_usernames text[] not null default '{}',
  bio text,
  profile_description text,
  profile_image_asset_id uuid references public.media_assets (id) on delete set null,
  cover_image_asset_id uuid references public.media_assets (id) on delete set null,
  brand_voice text,
  audience text,
  content_pillars text[] not null default '{}',
  initial_hooks text[] not null default '{}',
  -- The 30-post plan and the human setup checklist.
  first_posts jsonb not null default '[]'::jsonb,
  manual_checklist jsonb not null default '[]'::jsonb,

  origin app.output_origin not null default 'mock',
  -- Set once the user confirms they created the account themselves and connected
  -- it. Never set by the system on the user's behalf.
  linked_account_id uuid references public.connected_accounts (id) on delete set null,

  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.account_launch_kits');
select app.apply_workspace_rls('public.account_launch_kits', 'content.create', 'content.delete');

-- ── 0009_publishing.sql ──
-- =============================================================================
-- 0009 — PUBLISHING
--
-- The requirement driving every constraint here: "never duplicate a post because
-- of a retry."
--
-- Retries are not optional — platform APIs time out, return 502s, and sometimes
-- succeed while failing to tell us. So duplicate prevention cannot live in
-- application logic that a crash can interrupt between "posted" and "recorded
-- that we posted". It has to be a database constraint.
--
-- Three mechanisms, in layers:
--   1. `scheduled_posts` is unique on (content_variant_id, connected_account_id,
--      scheduled_for) — the same content cannot be double-booked to the same
--      account at the same time.
--   2. `publishing_jobs` is unique on `idempotency_key`, derived from the
--      scheduled post. A replayed enqueue collides instead of creating a job.
--   3. `publishing_attempts` records every attempt separately from the job, so a
--      retry is an INSERT into attempts, never a mutation that loses history —
--      and `external_post_id` unique per account proves at the database level
--      that one post was created, not three.
-- =============================================================================

create table public.publishing_plans (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  campaign_id uuid references public.campaigns (id) on delete cascade,

  name text,
  -- Confirmed counts, computed and shown to the user *before* anything is
  -- created. Stored so the audit trail records what was approved, not just what
  -- happened.
  planned_post_count integer not null default 0 check (planned_post_count >= 0),
  planned_account_count integer not null default 0 check (planned_account_count >= 0),
  estimated_usage_credits integer not null default 0 check (estimated_usage_credits >= 0),

  cadence text check (cadence in ('asap', 'daily', 'weekdays', 'custom', 'even_spread')),
  posts_per_day integer check (posts_per_day is null or posts_per_day > 0),
  time_windows jsonb not null default '[]'::jsonb,
  timezone text not null default 'UTC',

  starts_on date,
  ends_on date,
  constraint publishing_plans_range check (ends_on is null or starts_on is null or ends_on >= starts_on),

  -- Warnings surfaced at plan time: duplicate assets, repeated hooks, frequency
  -- limits, capability mismatches. Retained so the record shows the user was told.
  warnings jsonb not null default '[]'::jsonb,

  status text not null default 'draft'
    check (status in ('draft', 'previewed', 'confirmed', 'executing', 'completed', 'cancelled')),
  -- Explicit confirmation of an expensive batch. Nothing executes without it.
  confirmed_at timestamptz,
  confirmed_by uuid references auth.users (id) on delete set null,

  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint publishing_plans_confirmation_complete
    check ((confirmed_at is null) = (confirmed_by is null))
);

select app.attach_touch_trigger('public.publishing_plans');
select app.apply_workspace_rls('public.publishing_plans', 'content.publish', 'content.publish');

-- -----------------------------------------------------------------------------
-- SCHEDULED POSTS
-- The intent: this variant, to this account, at this time.
-- -----------------------------------------------------------------------------
create table public.scheduled_posts (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  publishing_plan_id uuid references public.publishing_plans (id) on delete set null,
  campaign_id uuid references public.campaigns (id) on delete set null,
  content_variant_id uuid not null references public.content_variants (id) on delete cascade,
  connected_account_id uuid not null references public.connected_accounts (id) on delete cascade,

  platform app.platform not null,
  scheduled_for timestamptz not null,
  timezone text not null default 'UTC',

  status app.publish_status not null default 'draft',

  caption text,
  first_comment text,
  -- Platform-specific fields: YouTube title/category, TikTok privacy level,
  -- Instagram collaborator tags. Genuinely heterogeneous per platform, which is
  -- the one case where JSONB beats columns.
  platform_options jsonb not null default '{}'::jsonb,

  requires_approval boolean not null default true,
  approved_at timestamptz,
  approved_by uuid references auth.users (id) on delete set null,

  published_at timestamptz,
  -- The platform's own post id. Unique per account: the database itself refuses
  -- to record the same remote post twice, so a retry that already succeeded
  -- cannot be logged as a second post.
  external_post_id text,
  external_permalink text,

  cancelled_at timestamptz,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Layer 1 of duplicate prevention.
  unique (content_variant_id, connected_account_id, scheduled_for),

  constraint scheduled_posts_approval_complete
    check ((approved_at is null) = (approved_by is null)),
  -- A published post must know where it went. Without this, a partially-written
  -- success is indistinguishable from a pending one and gets retried.
  constraint scheduled_posts_published_has_id
    check (status <> 'published' or external_post_id is not null)
);

select app.attach_touch_trigger('public.scheduled_posts');
select app.apply_workspace_rls('public.scheduled_posts', 'content.publish', 'content.publish');

-- Layer 3: one remote post per account, enforced by the database.
create unique index scheduled_posts_external_unique
  on public.scheduled_posts (connected_account_id, external_post_id)
  where external_post_id is not null;

-- The calendar's primary query.
create index scheduled_posts_calendar_idx
  on public.scheduled_posts (workspace_id, scheduled_for)
  where cancelled_at is null;
create index scheduled_posts_status_idx on public.scheduled_posts (status, scheduled_for)
  where status in ('scheduled', 'queued', 'uploading', 'publishing');
create index scheduled_posts_account_idx on public.scheduled_posts (connected_account_id, scheduled_for desc);
create index scheduled_posts_awaiting_approval_idx
  on public.scheduled_posts (workspace_id, scheduled_for)
  where status = 'awaiting_review';

-- -----------------------------------------------------------------------------
-- PUBLISHING JOBS
-- The unit of work. Separate from the scheduled post so a job can be retried,
-- cancelled and audited without mutating the user's intent.
-- -----------------------------------------------------------------------------
create table public.publishing_jobs (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  scheduled_post_id uuid not null references public.scheduled_posts (id) on delete cascade,

  status app.job_status not null default 'pending',
  priority smallint not null default 5 check (priority between 1 and 9),

  attempts integer not null default 0 check (attempts >= 0),
  max_attempts integer not null default 3 check (max_attempts >= 1),

  run_after timestamptz not null default now(),
  started_at timestamptz,
  completed_at timestamptz,

  -- Held by a worker while processing, with a lease so a crashed worker's job
  -- becomes reclaimable instead of stuck in `running` forever.
  locked_by text,
  locked_until timestamptz,

  failure_code text,
  failure_message text,
  -- Whether re-running is safe. A timeout after the upload began is NOT safely
  -- retryable without first checking the platform for an existing post, and the
  -- failure UI must say so rather than offering a retry button.
  retry_safe boolean not null default true,

  -- Layer 2 of duplicate prevention.
  idempotency_key text not null,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (idempotency_key),
  constraint publishing_jobs_attempts_bound check (attempts <= max_attempts + 1)
);

select app.attach_touch_trigger('public.publishing_jobs');
-- Read-only to clients: a client that could set `status = 'completed'` could mark
-- a post published without it ever being published. Cancellation goes through a
-- server action, not a direct update.
select app.apply_workspace_readonly_rls('public.publishing_jobs');

-- The worker's claim query.
create index publishing_jobs_claimable_idx
  on public.publishing_jobs (status, priority, run_after)
  where status in ('pending', 'queued');
create index publishing_jobs_lease_idx on public.publishing_jobs (locked_until)
  where locked_until is not null;
create index publishing_jobs_post_idx on public.publishing_jobs (scheduled_post_id);

-- -----------------------------------------------------------------------------
-- PUBLISHING ATTEMPTS
-- Append-only. One row per real call to a platform, which is what makes the
-- audit trail complete and what a support investigation reads.
-- -----------------------------------------------------------------------------
create table public.publishing_attempts (
  id uuid primary key default extensions.gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  publishing_job_id uuid not null references public.publishing_jobs (id) on delete cascade,
  attempt_number integer not null check (attempt_number >= 1),

  started_at timestamptz not null default now(),
  finished_at timestamptz,
  outcome text not null default 'running'
    check (outcome in ('running', 'succeeded', 'failed', 'aborted', 'skipped_duplicate')),

  http_status integer,
  platform_error_code text,
  platform_error_message text,
  external_post_id text,

  created_at timestamptz not null default now(),
  unique (publishing_job_id, attempt_number)
);

select app.apply_workspace_readonly_rls('public.publishing_attempts');

create index publishing_attempts_job_idx on public.publishing_attempts (publishing_job_id, attempt_number);

-- ── 0010_analytics.sql ──
-- =============================================================================
-- 0010 — ANALYTICS
--
-- Every metric table is read-only to clients. A user who could insert their own
-- analytics could fabricate the performance data the product's recommendations
-- are derived from.
--
-- Metrics are stored as SNAPSHOTS, not as mutable running totals. Platform APIs
-- return cumulative counters that can go down (a deleted comment, a retracted
-- view), arrive late, and be revised days later. Overwriting a single row loses
-- the ability to compute a delta for a period, which is exactly what every chart
-- needs. `metric_snapshots` is therefore append-only and time-series shaped.
--
-- Cross-platform normalisation is deliberately NOT done in the schema. A TikTok
-- "view" and a YouTube "view" are different events with different thresholds;
-- summing them into one number produces a figure that looks authoritative and
-- means nothing. Platform-level rows are stored as reported, and any comparison
-- surface must state its methodology.
-- =============================================================================

create table public.content_metrics (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  scheduled_post_id uuid not null references public.scheduled_posts (id) on delete cascade,
  connected_account_id uuid not null references public.connected_accounts (id) on delete cascade,
  content_variant_id uuid references public.content_variants (id) on delete set null,
  campaign_id uuid references public.campaigns (id) on delete set null,
  platform app.platform not null,

  -- The moment the platform's figures describe, truncated to the hour.
  captured_at timestamptz not null,

  -- Nullable throughout, and that is the point: platforms expose different
  -- subsets, and 0 would be a lie about a metric that was never reported. Every
  -- chart must distinguish "zero" from "not available".
  views bigint check (views is null or views >= 0),
  reach bigint check (reach is null or reach >= 0),
  impressions bigint check (impressions is null or impressions >= 0),
  likes bigint check (likes is null or likes >= 0),
  comments bigint check (comments is null or comments >= 0),
  shares bigint check (shares is null or shares >= 0),
  saves bigint check (saves is null or saves >= 0),
  clicks bigint check (clicks is null or clicks >= 0),
  followers_gained integer,
  -- Basis points (1/100th of a percent) as an integer, not a float percentage.
  -- Keeps aggregation exact and avoids 0.30000000000000004 in a UI.
  engagement_rate_bp integer check (engagement_rate_bp is null or engagement_rate_bp >= 0),
  completion_rate_bp integer check (completion_rate_bp is null or completion_rate_bp between 0 and 10000),
  average_watch_ms integer check (average_watch_ms is null or average_watch_ms >= 0),
  three_second_views bigint check (three_second_views is null or three_second_views >= 0),

  -- Retention curve as reported, when the platform provides one.
  retention_curve jsonb,

  -- Distinguishes real platform data from seeded demo rows. Every analytics
  -- surface reads this to decide whether the "Demo data" label is required, and
  -- demo rows are never mixed into a real total.
  origin app.output_origin not null default 'provider',

  created_at timestamptz not null default now(),

  -- One snapshot per post per hour. Makes a re-run of the metrics sync idempotent
  -- rather than inflating the series with duplicates.
  unique (scheduled_post_id, captured_at)
);

select app.apply_workspace_readonly_rls('public.content_metrics');

create index content_metrics_post_time_idx on public.content_metrics (scheduled_post_id, captured_at desc);
create index content_metrics_workspace_time_idx on public.content_metrics (workspace_id, captured_at desc);
create index content_metrics_campaign_idx on public.content_metrics (campaign_id, captured_at desc);
create index content_metrics_platform_idx on public.content_metrics (workspace_id, platform, captured_at desc);

-- -----------------------------------------------------------------------------
-- ACCOUNT METRICS
-- -----------------------------------------------------------------------------
create table public.account_metrics (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  connected_account_id uuid not null references public.connected_accounts (id) on delete cascade,
  platform app.platform not null,

  captured_on date not null,

  follower_count bigint check (follower_count is null or follower_count >= 0),
  followers_gained integer,
  followers_lost integer,
  profile_views bigint,
  reach bigint,
  impressions bigint,
  total_views bigint,
  posts_published integer check (posts_published is null or posts_published >= 0),

  origin app.output_origin not null default 'provider',
  created_at timestamptz not null default now(),

  unique (connected_account_id, captured_on)
);

select app.apply_workspace_readonly_rls('public.account_metrics');

create index account_metrics_account_date_idx on public.account_metrics (connected_account_id, captured_on desc);
create index account_metrics_workspace_date_idx on public.account_metrics (workspace_id, captured_on desc);

-- -----------------------------------------------------------------------------
-- DAILY ROLLUP
--
-- Pre-aggregated per workspace/day/platform. The dashboard's KPI row and
-- timeline read this instead of scanning raw snapshots: with thousands of
-- snapshots the raw aggregate is too slow for a page load, and the brief forbids
-- pulling raw events into the browser to aggregate client-side.
--
-- Maintained by the metrics sync worker, and derivable from the tables above —
-- so a corrupted rollup can be rebuilt rather than being a second source of truth.
-- -----------------------------------------------------------------------------
create table public.analytics_daily (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  day date not null,
  platform app.platform,
  brand_id uuid references public.brands (id) on delete set null,

  views bigint not null default 0,
  reach bigint not null default 0,
  engagements bigint not null default 0,
  followers_gained integer not null default 0,
  posts_published integer not null default 0,
  -- Averages stored as basis points, weighted by the worker at write time.
  avg_completion_bp integer,
  avg_engagement_bp integer,

  -- Demo rows are rolled up separately so they can never contaminate a real total.
  origin app.output_origin not null default 'provider',
  computed_at timestamptz not null default now(),

  unique (workspace_id, day, platform, brand_id, origin)
);

select app.apply_workspace_readonly_rls('public.analytics_daily');

create index analytics_daily_workspace_day_idx on public.analytics_daily (workspace_id, day desc);

-- -----------------------------------------------------------------------------
-- EXPERIMENTS
--
-- Note what is absent: no `p_value`, no `is_significant`. The brief forbids
-- claiming statistical significance without implementing a correct method, and a
-- boolean column named `is_significant` is the fastest way to end up asserting
-- one. `confidence_state` holds the honest vocabulary instead.
-- -----------------------------------------------------------------------------
create type app.experiment_confidence as enum (
  'no_data',
  'early_signal',
  'inconclusive',
  'promising',
  'enough_observations'
);

create table public.experiments (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  campaign_id uuid references public.campaigns (id) on delete set null,

  name text not null,
  hypothesis text,
  variable text not null check (variable in
    ('hook', 'first_frame', 'duration', 'caption', 'cta', 'thumbnail', 'voice', 'music', 'platform', 'account', 'posting_time')),
  primary_metric text not null,
  secondary_metric text,

  status text not null default 'draft'
    check (status in ('draft', 'running', 'paused', 'concluded', 'abandoned')),
  confidence_state app.experiment_confidence not null default 'no_data',
  -- Prose, deliberately. A number here would be read as a guarantee.
  confidence_notes text,
  outcome_summary text,

  started_at timestamptz,
  ends_at timestamptz,
  min_observations integer check (min_observations is null or min_observations > 0),
  concluded_at timestamptz,

  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.experiments');
select app.apply_workspace_rls('public.experiments', 'campaign.manage', 'content.delete');

create table public.experiment_variants (
  id uuid primary key default extensions.gen_random_uuid(),
  experiment_id uuid not null references public.experiments (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  content_variant_id uuid references public.content_variants (id) on delete set null,
  label text not null,
  is_control boolean not null default false,
  created_at timestamptz not null default now(),
  unique (experiment_id, label)
);

select app.apply_workspace_rls('public.experiment_variants', 'campaign.manage', 'content.delete');

-- Exactly one control per experiment: a comparison without a baseline is not one.
create unique index experiment_variants_one_control
  on public.experiment_variants (experiment_id)
  where is_control;

-- -----------------------------------------------------------------------------
-- LEARNING INSIGHTS
--
-- `evidence` is not decoration. The post-analytics screen must say "not enough
-- data to make a reliable recommendation" rather than inventing an explanation,
-- so an insight row that cannot cite the observations behind it is rejected by
-- the constraint below.
-- -----------------------------------------------------------------------------
create table public.learning_insights (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  campaign_id uuid references public.campaigns (id) on delete set null,
  content_variant_id uuid references public.content_variants (id) on delete set null,

  kind text not null check (kind in ('what_worked', 'what_lost_attention', 'what_to_test')),
  statement text not null,
  -- The observations this claim rests on: sample size, metric, comparison basis.
  evidence jsonb not null,
  observation_count integer not null check (observation_count >= 0),
  confidence_state app.experiment_confidence not null default 'early_signal',

  origin app.output_origin not null default 'mock',
  created_at timestamptz not null default now(),

  -- An insight with no observations behind it is a fabrication. The database
  -- refuses to store one.
  constraint learning_insights_needs_evidence
    check (observation_count > 0 and evidence <> '{}'::jsonb)
);

select app.apply_workspace_readonly_rls('public.learning_insights');

create index learning_insights_variant_idx on public.learning_insights (content_variant_id);
create index learning_insights_campaign_idx on public.learning_insights (campaign_id);

-- ── 0011_jobs_usage_audit.sql ──
-- =============================================================================
-- 0011 — JOBS, ACTIVITY, USAGE, AUDIT
-- =============================================================================

-- -----------------------------------------------------------------------------
-- JOBS
--
-- The generic queue. Persisted in Postgres so the product works with no Redis
-- configured; when REDIS_URL is set the same rows are the durable record behind
-- a BullMQ queue. Either way the database, not the queue, is the source of truth
-- for "did this run" — an in-memory queue that loses a job leaves no evidence.
-- -----------------------------------------------------------------------------
create table public.jobs (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  user_id uuid references auth.users (id) on delete set null,

  type text not null check (type in (
    'campaign.plan',
    'content.script',
    'content.storyboard',
    'asset.image.generate',
    'asset.video.generate',
    'asset.voice.generate',
    'content.render',
    'content.transcode',
    'content.quality_check',
    'content.publish',
    'content.metrics.sync',
    'account.sync'
  )),

  status app.job_status not null default 'pending',
  priority smallint not null default 5 check (priority between 1 and 9),
  progress smallint not null default 0 check (progress between 0 and 100),

  payload jsonb not null default '{}'::jsonb,
  result jsonb,

  attempts integer not null default 0 check (attempts >= 0),
  max_attempts integer not null default 3 check (max_attempts >= 1),

  run_after timestamptz not null default now(),
  started_at timestamptz,
  completed_at timestamptz,

  locked_by text,
  locked_until timestamptz,

  provider text,
  external_job_id text,
  cost_cents integer not null default 0 check (cost_cents >= 0),

  failure_code text,
  failure_message text,

  -- Every enqueue supplies one. Uniqueness makes "enqueue this batch again"
  -- safe: the second call collides on existing rows instead of doubling the work.
  idempotency_key text not null,

  -- Parent/child so a batch of 100 renders has one row to report progress on.
  parent_job_id uuid references public.jobs (id) on delete cascade,

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  unique (idempotency_key)
);

select app.attach_touch_trigger('public.jobs');
-- Read-only to clients. Cancelling goes through a server action that verifies
-- permission; a direct UPDATE would let a viewer cancel a colleague's render.
select app.apply_workspace_readonly_rls('public.jobs');

create index jobs_claimable_idx on public.jobs (status, priority, run_after)
  where status in ('pending', 'queued');
create index jobs_workspace_status_idx on public.jobs (workspace_id, status, created_at desc);
create index jobs_lease_idx on public.jobs (locked_until) where locked_until is not null;
create index jobs_parent_idx on public.jobs (parent_job_id) where parent_job_id is not null;
create index jobs_external_idx on public.jobs (provider, external_job_id)
  where external_job_id is not null;

-- Append-only state transitions. Separate from `jobs` because the job row holds
-- current state while this holds history, and a debugging session needs both.
create table public.job_events (
  id bigint generated always as identity primary key,
  job_id uuid not null references public.jobs (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  from_status app.job_status,
  to_status app.job_status not null,
  detail text,
  created_at timestamptz not null default now()
);

select app.apply_workspace_readonly_rls('public.job_events');
create index job_events_job_idx on public.job_events (job_id, created_at);

-- -----------------------------------------------------------------------------
-- ACTIVITY AND NOTIFICATIONS
-- -----------------------------------------------------------------------------
create table public.activity_events (
  id bigint generated always as identity primary key,
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  actor_id uuid references auth.users (id) on delete set null,
  -- Null actor means the system did it, which the activity feed renders
  -- differently from a teammate action.
  kind text not null,
  subject_type text,
  subject_id uuid,
  summary text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

select app.apply_workspace_readonly_rls('public.activity_events');
create index activity_events_workspace_time_idx on public.activity_events (workspace_id, created_at desc);

create table public.notifications (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid references public.workspaces (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,

  kind text not null check (kind in (
    'job_completed', 'job_failed', 'account_disconnected', 'approval_required',
    'publishing_completed', 'publishing_failed', 'usage_warning',
    'team_invitation', 'analytics_insight'
  )),
  title text not null,
  body text,
  link_path text,
  metadata jsonb not null default '{}'::jsonb,

  read_at timestamptz,
  created_at timestamptz not null default now()
);

alter table public.notifications enable row level security;
alter table public.notifications force row level security;

-- Strictly personal, and the only mutation a user may make is marking one read.
create policy notifications_select_own on public.notifications
  for select to authenticated using (user_id = auth.uid());

create policy notifications_update_own on public.notifications
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- Two indexes, deliberately. The partial one serves the unread badge, which is
-- the hot query. The full one serves the RLS policy itself (`user_id =
-- auth.uid()`), which applies to read notifications too — a partial index cannot
-- satisfy a scan of the whole notification centre.
create index notifications_user_unread_idx on public.notifications (user_id, created_at desc)
  where read_at is null;
create index notifications_user_idx on public.notifications (user_id, created_at desc);

-- -----------------------------------------------------------------------------
-- COMMENTS AND APPROVALS
-- -----------------------------------------------------------------------------
create table public.comments (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  content_item_id uuid references public.content_items (id) on delete cascade,
  content_variant_id uuid references public.content_variants (id) on delete cascade,
  campaign_id uuid references public.campaigns (id) on delete cascade,
  author_id uuid not null references auth.users (id) on delete cascade,
  parent_id uuid references public.comments (id) on delete cascade,
  body text not null check (length(trim(body)) > 0),
  -- Frame-anchored review notes: "the cut at 0:04 is early".
  anchor_frame integer check (anchor_frame is null or anchor_frame >= 0),
  resolved_at timestamptz,
  resolved_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.comments');

alter table public.comments enable row level security;
alter table public.comments force row level security;

create policy comments_select on public.comments
  for select to authenticated using (app.is_workspace_member(workspace_id));

-- Any workspace member may comment — reviewing does not require write access to
-- the content itself.
create policy comments_insert on public.comments
  for insert to authenticated
  with check (app.is_workspace_member(workspace_id) and author_id = auth.uid());

-- Editing and deleting are limited to the author. A teammate silently rewriting
-- your review note would make the approval trail worthless.
create policy comments_modify_own on public.comments
  for update to authenticated
  using (author_id = auth.uid())
  with check (author_id = auth.uid());

create policy comments_delete_own on public.comments
  for delete to authenticated using (author_id = auth.uid());

create index comments_item_idx on public.comments (content_item_id, created_at);
create index comments_workspace_open_idx on public.comments (workspace_id) where resolved_at is null;

create table public.approval_requests (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  content_item_id uuid references public.content_items (id) on delete cascade,
  scheduled_post_id uuid references public.scheduled_posts (id) on delete cascade,
  requested_by uuid not null references auth.users (id) on delete cascade,
  assigned_to uuid references auth.users (id) on delete set null,
  status text not null default 'pending'
    check (status in ('pending', 'approved', 'rejected', 'withdrawn')),
  decided_by uuid references auth.users (id) on delete set null,
  decided_at timestamptz,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint approval_requests_decision_complete
    check ((decided_at is null) = (decided_by is null))
);

select app.attach_touch_trigger('public.approval_requests');

alter table public.approval_requests enable row level security;
alter table public.approval_requests force row level security;

create policy approval_requests_select on public.approval_requests
  for select to authenticated using (app.is_workspace_member(workspace_id));

create policy approval_requests_insert on public.approval_requests
  for insert to authenticated
  with check (app.has_workspace_permission(workspace_id, 'content.create') and requested_by = auth.uid());

-- Deciding requires the approval permission specifically. This is the constraint
-- that makes the editor/reviewer split real rather than cosmetic.
create policy approval_requests_decide on public.approval_requests
  for update to authenticated
  using (app.has_workspace_permission(workspace_id, 'content.approve'))
  with check (app.has_workspace_permission(workspace_id, 'content.approve'));

create index approval_requests_pending_idx on public.approval_requests (workspace_id, created_at)
  where status = 'pending';

-- -----------------------------------------------------------------------------
-- USAGE LEDGER
--
-- Append-only, and the balance is a SUM over it rather than a mutable counter.
-- The brief requires this explicitly, and the reason is that a counter cannot be
-- audited: when a user disputes a charge there is no way to show what produced
-- the number. There is deliberately no UPDATE or DELETE policy, for anyone.
-- -----------------------------------------------------------------------------
create table public.usage_events (
  id bigint generated always as identity primary key,
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid references public.workspaces (id) on delete set null,
  user_id uuid references auth.users (id) on delete set null,

  kind text not null check (kind in (
    'video_generated', 'image_generated', 'voice_generated', 'render_minutes',
    'storage_bytes', 'post_published', 'account_connected', 'transcription_minutes'
  )),
  -- Integer quantity in the unit's smallest sensible increment (one video, one
  -- second, one byte). Never a float.
  quantity bigint not null check (quantity >= 0),
  unit text not null,

  credits_delta integer not null default 0,
  provider_cost_cents integer not null default 0 check (provider_cost_cents >= 0),

  generation_run_id uuid references public.generation_runs (id) on delete set null,
  job_id uuid references public.jobs (id) on delete set null,

  -- Same key as the job that caused it, so a retried job cannot bill twice.
  idempotency_key text not null,
  occurred_at timestamptz not null default now(),
  unique (idempotency_key, kind)
);

alter table public.usage_events enable row level security;
alter table public.usage_events force row level security;

-- Read requires the billing permission: an editor should not be able to see the
-- organisation's cost profile.
create policy usage_events_select on public.usage_events
  for select to authenticated
  using (app.has_org_permission(organization_id, 'billing.view'));

-- No insert/update/delete policies at all. Writes are service-role only, which is
-- what makes this a ledger rather than a table of suggestions.

create index usage_events_org_time_idx on public.usage_events (organization_id, occurred_at desc);
create index usage_events_kind_idx on public.usage_events (organization_id, kind, occurred_at desc);

create table public.credit_ledger (
  id bigint generated always as identity primary key,
  organization_id uuid not null references public.organizations (id) on delete cascade,
  -- Positive for grants and top-ups, negative for consumption. The balance is
  -- the sum; there is no stored balance to drift.
  delta integer not null,
  reason text not null check (reason in
    ('plan_grant', 'top_up', 'consumption', 'refund', 'adjustment', 'expiry')),
  usage_event_id bigint references public.usage_events (id) on delete set null,
  note text,
  idempotency_key text not null unique,
  occurred_at timestamptz not null default now()
);

alter table public.credit_ledger enable row level security;
alter table public.credit_ledger force row level security;

create policy credit_ledger_select on public.credit_ledger
  for select to authenticated
  using (app.has_org_permission(organization_id, 'billing.view'));

create index credit_ledger_org_idx on public.credit_ledger (organization_id, occurred_at desc);

create table public.subscriptions (
  id uuid primary key default extensions.gen_random_uuid(),
  organization_id uuid not null unique references public.organizations (id) on delete cascade,
  -- Feature-flagged: with no Stripe configured the product still tracks usage,
  -- it simply does not charge for it.
  provider text not null default 'none' check (provider in ('none', 'stripe')),
  external_customer_id text,
  external_subscription_id text,
  plan_code text not null default 'free',
  status text not null default 'active'
    check (status in ('active', 'trialing', 'past_due', 'cancelled', 'paused', 'unconfigured')),
  current_period_start timestamptz,
  current_period_end timestamptz,
  included_credits integer not null default 0 check (included_credits >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

select app.attach_touch_trigger('public.subscriptions');

alter table public.subscriptions enable row level security;
alter table public.subscriptions force row level security;

create policy subscriptions_select on public.subscriptions
  for select to authenticated
  using (app.has_org_permission(organization_id, 'billing.view'));

-- -----------------------------------------------------------------------------
-- AUDIT LOG
--
-- Append-only and never deleted. Records the actions the threat model cares
-- about: who connected or disconnected an account, who approved and who
-- published, who changed a role.
-- -----------------------------------------------------------------------------
create table public.audit_logs (
  id bigint generated always as identity primary key,
  organization_id uuid not null references public.organizations (id) on delete cascade,
  workspace_id uuid references public.workspaces (id) on delete set null,
  actor_id uuid references auth.users (id) on delete set null,
  actor_email text,

  action text not null,
  subject_type text,
  subject_id uuid,

  -- Truncated at the application layer before insert. A full IP and user agent
  -- are more personal data than an audit trail needs.
  ip_prefix text,
  user_agent_family text,

  before_state jsonb,
  after_state jsonb,
  created_at timestamptz not null default now()
);

alter table public.audit_logs enable row level security;
alter table public.audit_logs force row level security;

-- Visible to those who manage the team; writes are service-role only.
create policy audit_logs_select on public.audit_logs
  for select to authenticated
  using (app.has_org_permission(organization_id, 'team.manage'));

create index audit_logs_org_time_idx on public.audit_logs (organization_id, created_at desc);
create index audit_logs_subject_idx on public.audit_logs (subject_type, subject_id);

-- -----------------------------------------------------------------------------
-- WEBHOOK EVENTS
--
-- Inbound platform and provider callbacks. Stored before processing so a replayed
-- delivery is detected by the unique constraint rather than processed twice — the
-- webhook equivalent of the publishing idempotency key.
-- -----------------------------------------------------------------------------
create table public.webhook_events (
  id uuid primary key default extensions.gen_random_uuid(),
  source text not null,
  external_event_id text,
  event_type text,
  signature_verified boolean not null default false,
  payload jsonb not null,
  processed_at timestamptz,
  processing_error text,
  received_at timestamptz not null default now(),
  -- Replay protection.
  unique (source, external_event_id)
);

alter table public.webhook_events enable row level security;
alter table public.webhook_events force row level security;

-- No policies: service-role only. Webhook payloads can contain material from
-- other tenants and must never be client-readable.

create index webhook_events_unprocessed_idx on public.webhook_events (received_at)
  where processed_at is null;

-- ── 0012_storage.sql ──
-- =============================================================================
-- 0012 — STORAGE
--
-- All buckets are PRIVATE. Access is exclusively through short-lived signed URLs
-- minted server-side after an authorisation check.
--
-- Why not a public bucket for generated media: a public URL is permanent and
-- unguessable-only-by-obscurity. Once it appears in a browser history, a proxy
-- log, or a shared screenshot it is public forever, including after the user
-- deletes the asset. A user's unpublished campaign video is not public content.
--
-- OBJECT PATH CONVENTION — load-bearing, not cosmetic:
--
--     <workspace_id>/<asset_kind>/<asset_id>[.<ext>]
--
-- The policies below authorise on the FIRST path segment. `storage.foldername()`
-- returns the path segments, so `(storage.foldername(name))[1]` is the workspace
-- id, and membership in that workspace is the entire access check. Any code that
-- uploads outside this convention creates an object nobody can read.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  -- User uploads: the source material a campaign is built from.
  ('source-media', 'source-media', false, 524288000,
   array['video/mp4','video/quicktime','video/webm','audio/mpeg','audio/mp4','audio/wav',
         'image/jpeg','image/png','image/webp','image/avif','application/pdf']),

  -- Provider and renderer output.
  ('generated-media', 'generated-media', false, 524288000,
   array['video/mp4','video/webm','audio/mpeg','audio/wav','image/jpeg','image/png','image/webp']),

  ('brand-assets', 'brand-assets', false, 26214400,
   array['image/jpeg','image/png','image/webp','image/svg+xml','application/pdf']),

  ('avatars', 'avatars', false, 5242880,
   array['image/jpeg','image/png','image/webp']),

  ('exports', 'exports', false, 524288000,
   array['video/mp4','image/jpeg','image/png','application/zip','text/csv','application/pdf'])
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- Helper: is the caller a member of the workspace named by the object path?
--
-- SECURITY DEFINER for the same reason as the helpers in 0002 — it reads
-- membership tables that are themselves behind RLS.
--
-- Returns false on a malformed path rather than raising: a bad path must be
-- unreadable, not a 500.
-- -----------------------------------------------------------------------------
create or replace function app.storage_path_workspace_member(p_object_name text)
returns boolean
language plpgsql
security definer
set search_path = app, public, pg_catalog
stable
as $$
declare
  v_first text;
  v_workspace_id uuid;
begin
  v_first := (storage.foldername(p_object_name))[1];
  if v_first is null or v_first = '' then
    return false;
  end if;

  begin
    v_workspace_id := v_first::uuid;
  exception when invalid_text_representation then
    return false;
  end;

  return app.is_workspace_member(v_workspace_id);
end;
$$;

create or replace function app.storage_path_workspace_permission(
  p_object_name text,
  p_permission app.permission
)
returns boolean
language plpgsql
security definer
set search_path = app, public, pg_catalog
stable
as $$
declare
  v_first text;
  v_workspace_id uuid;
begin
  v_first := (storage.foldername(p_object_name))[1];
  if v_first is null or v_first = '' then
    return false;
  end if;

  begin
    v_workspace_id := v_first::uuid;
  exception when invalid_text_representation then
    return false;
  end;

  return app.has_workspace_permission(v_workspace_id, p_permission);
end;
$$;

grant execute on function
  app.storage_path_workspace_member(text),
  app.storage_path_workspace_permission(text, app.permission)
to authenticated, service_role;

-- -----------------------------------------------------------------------------
-- POLICIES
--
-- Tenant-scoped buckets share one pattern: read on membership, write on a
-- permission. Applied per bucket rather than generated, because there are only
-- four and the differences between them matter.
-- -----------------------------------------------------------------------------

-- --- source-media -----------------------------------------------------------
create policy "source_media_read" on storage.objects
  for select to authenticated
  using (
    bucket_id = 'source-media'
    and app.storage_path_workspace_member(name)
  );

create policy "source_media_insert" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'source-media'
    and app.storage_path_workspace_permission(name, 'content.create')
  );

create policy "source_media_update" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'source-media'
    and app.storage_path_workspace_permission(name, 'content.create')
  );

create policy "source_media_delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'source-media'
    and app.storage_path_workspace_permission(name, 'assets.delete')
  );

-- --- generated-media --------------------------------------------------------
-- Readable by members; NOT writable by clients. Provider and renderer output is
-- written by workers with the service-role key. A client that could write here
-- could substitute its own file for a "generated" asset, which would also
-- corrupt the provenance record in generation_runs.
create policy "generated_media_read" on storage.objects
  for select to authenticated
  using (
    bucket_id = 'generated-media'
    and app.storage_path_workspace_member(name)
  );

create policy "generated_media_delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'generated-media'
    and app.storage_path_workspace_permission(name, 'assets.delete')
  );

-- --- brand-assets -----------------------------------------------------------
create policy "brand_assets_read" on storage.objects
  for select to authenticated
  using (
    bucket_id = 'brand-assets'
    and app.storage_path_workspace_member(name)
  );

create policy "brand_assets_write" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'brand-assets'
    and app.storage_path_workspace_permission(name, 'campaign.manage')
  );

create policy "brand_assets_update" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'brand-assets'
    and app.storage_path_workspace_permission(name, 'campaign.manage')
  );

create policy "brand_assets_delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'brand-assets'
    and app.storage_path_workspace_permission(name, 'assets.delete')
  );

-- --- exports ----------------------------------------------------------------
create policy "exports_read" on storage.objects
  for select to authenticated
  using (
    bucket_id = 'exports'
    and app.storage_path_workspace_member(name)
  );

create policy "exports_delete" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'exports'
    and app.storage_path_workspace_permission(name, 'assets.delete')
  );

-- --- avatars ----------------------------------------------------------------
-- The one bucket keyed by user id rather than workspace id: an avatar belongs to
-- a person, not a tenant. Path convention is `<user_id>/<filename>`.
create policy "avatars_read_own" on storage.objects
  for select to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "avatars_write_own" on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "avatars_update_own" on storage.objects
  for update to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "avatars_delete_own" on storage.objects
  for delete to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ── 0013_bootstrap.sql ──
-- =============================================================================
-- 0013 — TENANT BOOTSTRAP
--
-- Creates the records a new user needs: profile, organisation, owner membership,
-- default workspace, workspace membership, default brand, onboarding progress,
-- subscription placeholder.
--
-- WHY A FUNCTION AND NOT A TRIGGER ON auth.users
--
-- A trigger is the tempting choice, and it is wrong here. If anything inside it
-- raises, the INSERT into `auth.users` is rolled back — so a bug in brand
-- creation makes sign-up itself fail, and Supabase reports it as "Database error
-- saving new user" with no indication of which statement failed. Debugging that
-- in production is miserable, and the user simply cannot sign up.
--
-- Calling this explicitly after authentication means a bootstrap failure leaves a
-- real, usable auth account that can be retried — the function is idempotent, so
-- retrying is safe — and the error surfaces where it can be read.
--
-- IDEMPOTENCY
--
-- OAuth callbacks are replayed: users double-click, refresh mid-redirect, and
-- browsers retry. Every insert below is therefore guarded by ON CONFLICT against
-- a real unique constraint, not by a preceding SELECT. A check-then-insert has a
-- race window; two concurrent callbacks would both see "no organisation" and both
-- create one. The constraints close that window in the database.
-- =============================================================================

create or replace function public.bootstrap_current_user(
  p_full_name text default null,
  p_avatar_url text default null
)
returns table (
  organization_id uuid,
  workspace_id uuid,
  brand_id uuid,
  onboarding_complete boolean,
  was_created boolean
)
language plpgsql
security definer
set search_path = public, app, pg_catalog
as $$
-- The RETURNS TABLE column names (organization_id, workspace_id, brand_id) are
-- also real column names, which makes a bare reference to them ambiguous inside
-- `on conflict (organization_id, user_id)` — PL/pgSQL cannot tell whether the
-- identifier means the OUT parameter or the column, and raises.
--
-- This pragma resolves every ambiguous identifier to the column, which is correct
-- here because no statement below intends the OUT parameter: those are only ever
-- assigned through the v_-prefixed locals and returned positionally.
--
-- The alternative was renaming the outputs to `out_organization_id`, rejected
-- because these names are the function's public API and the caller reads them.
#variable_conflict use_column
declare
  v_user_id uuid := auth.uid();
  v_email text;
  v_name text;
  v_org_id uuid;
  v_workspace_id uuid;
  v_brand_id uuid;
  v_slug text;
  v_created boolean := false;
  v_onboarded boolean;
begin
  -- Runs as definer, so it must establish the caller itself rather than trusting
  -- a parameter. A `p_user_id` argument here would let any authenticated user
  -- bootstrap — and then join — another user's organisation.
  if v_user_id is null then
    raise exception 'bootstrap_current_user must be called by an authenticated user'
      using errcode = '42501';
  end if;

  select u.email into v_email from auth.users u where u.id = v_user_id;

  -- Prefer the name the caller passes (from the OAuth identity), fall back to the
  -- email local part, and never invent one.
  v_name := coalesce(nullif(trim(p_full_name), ''), split_part(coalesce(v_email, 'member'), '@', 1));

  -- --- profile -------------------------------------------------------------
  insert into public.profiles (id, email, full_name, avatar_url)
  values (v_user_id, v_email, nullif(trim(p_full_name), ''), nullif(trim(p_avatar_url), ''))
  on conflict (id) do update
    -- Refresh only from a non-null incoming value, so a later email sign-in does
    -- not blank the name and avatar an OAuth sign-in provided.
    set email      = coalesce(excluded.email, public.profiles.email),
        full_name  = coalesce(excluded.full_name, public.profiles.full_name),
        avatar_url = coalesce(excluded.avatar_url, public.profiles.avatar_url);

  -- --- existing organisation? ----------------------------------------------
  -- Owned organisations first: a user invited to someone else's organisation must
  -- not be treated as already bootstrapped, or they never get their own.
  select m.organization_id into v_org_id
  from public.organization_members m
  where m.user_id = v_user_id and m.role = 'owner'
  order by m.created_at
  limit 1;

  if v_org_id is null then
    -- Slug must be unique organisation-wide. Derived from the name, then
    -- suffixed with a short random token rather than looping on a collision
    -- check — a loop is another race, and the token makes one attempt sufficient.
    v_slug := regexp_replace(lower(v_name), '[^a-z0-9]+', '-', 'g');
    v_slug := trim(both '-' from v_slug);
    if length(v_slug) < 2 then
      v_slug := 'workspace';
    end if;
    v_slug := left(v_slug, 40) || '-' || substr(replace(extensions.gen_random_uuid()::text, '-', ''), 1, 8);

    insert into public.organizations (name, slug, account_type, created_by)
    values (v_name, v_slug, 'personal', v_user_id)
    returning id into v_org_id;

    v_created := true;
  end if;

  -- --- owner membership ----------------------------------------------------
  insert into public.organization_members (organization_id, user_id, role, accepted_at)
  values (v_org_id, v_user_id, 'owner', now())
  on conflict (organization_id, user_id) do nothing;

  -- --- default workspace ---------------------------------------------------
  select w.id into v_workspace_id
  from public.workspaces w
  where w.organization_id = v_org_id and w.is_default and w.deleted_at is null
  limit 1;

  if v_workspace_id is null then
    insert into public.workspaces (organization_id, name, slug, is_default, created_by)
    values (v_org_id, 'Default workspace', 'default', true, v_user_id)
    -- Collides with either the (organization_id, slug) constraint or the
    -- one-default-per-org partial index if a concurrent call won the race.
    on conflict (organization_id, slug) do nothing
    returning id into v_workspace_id;

    -- ON CONFLICT DO NOTHING returns no row, so re-read after losing the race.
    if v_workspace_id is null then
      select w.id into v_workspace_id
      from public.workspaces w
      where w.organization_id = v_org_id and w.slug = 'default'
      limit 1;
    end if;
  end if;

  insert into public.workspace_members (workspace_id, organization_id, user_id, role)
  values (v_workspace_id, v_org_id, v_user_id, 'owner')
  on conflict (workspace_id, user_id) do nothing;

  -- --- placeholder brand ---------------------------------------------------
  -- Marked `is_placeholder` so the UI prompts the user to complete it rather than
  -- presenting an unnamed brand as configured.
  select b.id into v_brand_id
  from public.brands b
  where b.workspace_id = v_workspace_id and b.is_default and b.deleted_at is null
  limit 1;

  if v_brand_id is null then
    insert into public.brands (
      organization_id, workspace_id, name, is_placeholder, is_default, created_by
    )
    values (v_org_id, v_workspace_id, v_name, true, true, v_user_id)
    returning id into v_brand_id;

    insert into public.brand_profiles (brand_id, workspace_id)
    values (v_brand_id, v_workspace_id)
    on conflict (brand_id) do nothing;
  end if;

  -- --- onboarding ----------------------------------------------------------
  insert into public.onboarding_progress (organization_id, user_id)
  values (v_org_id, v_user_id)
  on conflict (organization_id, user_id) do nothing;

  select (op.completed_at is not null) into v_onboarded
  from public.onboarding_progress op
  where op.organization_id = v_org_id and op.user_id = v_user_id;

  -- --- billing placeholder -------------------------------------------------
  -- `unconfigured` rather than `active`: with no Stripe configured the product
  -- tracks usage but charges nothing, and the status says so.
  insert into public.subscriptions (organization_id, provider, plan_code, status)
  values (v_org_id, 'none', 'free', 'unconfigured')
  on conflict (organization_id) do nothing;

  -- --- audit ---------------------------------------------------------------
  if v_created then
    insert into public.audit_logs (organization_id, workspace_id, actor_id, actor_email, action, subject_type, subject_id)
    values (v_org_id, v_workspace_id, v_user_id, v_email, 'organization.bootstrapped', 'organization', v_org_id);
  end if;

  return query select v_org_id, v_workspace_id, v_brand_id, coalesce(v_onboarded, false), v_created;
end;
$$;

comment on function public.bootstrap_current_user is
  'Idempotently creates the tenant records for auth.uid(). Safe to call on every sign-in. See 0013 for why this is not a trigger.';

revoke all on function public.bootstrap_current_user(text, text) from public, anon;
grant execute on function public.bootstrap_current_user(text, text) to authenticated;

-- ── 0014_capabilities_and_assertions.sql ──
